    ["Frequency penalty"] = "Kara za częstotliwość",
    ["Advanced parameters (JSON)"] = "Zaawansowane parametry (JSON)",
    ["Extra settings added to every reply, written as a JSON object, for example {example}. Use it for samplers that have no box above. A setting that has its own box above is refused. If a server refuses a setting, it is left out and the reply still comes."] = "Dodatkowe ustawienia dodawane do każdej odpowiedzi, zapisane jako obiekt JSON, na przykład {example}. Używaj ich dla samplerów, które nie mają pola powyżej. Ustawienie, które ma własne pole powyżej, zostanie odrzucone. Jeśli serwer odrzuci ustawienie, zostanie ono pominięte, a odpowiedź i tak przyjdzie.",
    ["Mistral takes only the settings shown here. Top K, Min P and the advanced JSON are for Local AI and Custom models."] = "Mistral przyjmuje tylko ustawienia pokazane tutaj. Top K, Min P i zaawansowany JSON dotyczą modeli Local AI i własnych.",
    ["Mistral does not take this setting."] = "Mistral nie przyjmuje tego ustawienia.",
    ["That is not valid JSON."] = "To nie jest poprawny JSON.",
    ["This must be a JSON object, for example {example}."] = "To musi być obiekt JSON, na przykład {example}.",
    ["Too many keys. Keep {max} or fewer."] = "Za dużo kluczy. Zostaw {max} lub mniej.",
    ["“{name}” is not a usable key name. Use letters, digits and underscores."] = "“{name}” nie jest użytecznym nazwą klucza. Użyj liter, cyfr i podkreśleń.",
    ["“{name}” has its own setting in this form. Use that instead."] = "“{name}” ma w tym formularzu własne ustawienie. Użyj go zamiast tego.",
    ["Use the Longest reply box for the length of a reply, not “{name}”."] = "Do długości odpowiedzi użyj pola Najdłuższa odpowiedź, a nie “{name}”.",
    ["“{name}” is set by the mod and cannot be changed here."] = "“{name}” ustawia mod i nie można go tu zmienić.",
    ["“{name}” needs a number, a text, true or false, or a list of those."] = "“{name}” wymaga liczby, tekstu, wartości true lub false albo listy takich wartości.",
    ["Longest character description, in characters"] = "Najdłuższy opis postaci, w znakach",
    ["Earlier turns kept"] = "Zachowane poprzednie tury",
    ["Right-now sentence"] = "Zdanie o chwili obecnej",
    ["Notes for this turn"] = "Uwagi na tę turę",
    ["That prompting option was not found."] = "Nie znaleziono tej opcji promptu.",
    ["Keep at least one rule."] = "Zostaw co najmniej jedną zasadę.",
    ["Rule {n} is empty. Write the rule or delete it."] = "Zasada {n} jest pusta. Napisz zasadę albo ją usuń.",
    ["Rule {n} is too long. Keep each one under {max} characters."] = "Zasada {n} jest za długa. Utrzymaj każdą poniżej {max} znaków.",
    ["The rules are too long together. Keep them under {max} characters in all."] = "Zasady są razem za długie. Utrzymaj je poniżej {max} znaków łącznie.",
    ["This text is too long. Keep it under {max} characters."] = "Ten tekst jest za długi. Utrzymaj go poniżej {max} znaków.",
    ["This text cannot be empty."] = "Ten tekst nie może być pusty.",
    ["Use a number from {min} to {max}."] = "Użyj liczby od {min} do {max}.",
    ["Too many stop texts. Keep {max} or fewer."] = "Za dużo tekstów zatrzymania. Zostaw nie więcej niż {max}.",
    ["A stop text is too long. Keep each one under {max} characters."] = "Tekst zatrzymania jest za długi. Utrzymaj każdy poniżej {max} znaków.",
    ["{field}: {message}"] = "{field}: {message}",
    ["In use now"] = "Używane teraz",
    ["How each conversation option is told to answer. Every option has its own prompting. A change counts from the next reply, and nothing needs restarting."] = "Jak ma odpowiadać każda opcja rozmowy. Każda opcja ma własny prompt. Zmiana działa od następnej odpowiedzi, bez potrzeby restartu.",
    ["The facts the characters get from the game and a short list of safety filters cannot be edited here. Convai’s prompting lives on Convai’s side."] = "Fakty, które postacie dostają z gry, oraz krótka lista filtrów bezpieczeństwa nie mogą być tu edytowane. Prompt Convai znajduje się po stronie Convai.",
    ["Mistral and Local AI"] = "Mistral i Local AI",
    ["Lite and Standard are the two Local AI model sizes. “Mature on” is used while Mature content is on."] = "Lite i Standard to dwa rozmiary modelu Local AI. „Dla dorosłych wł.” jest używane, gdy treści dla dorosłych są włączone.",
    ["Your Custom models and APIs"] = "Twoje własne modele i API",
    ["A Custom model appears here once you choose Custom as the conversation provider and set a model."] = "Własny model pojawi się tutaj, gdy wybierzesz Własny jako dostawcę rozmów i ustawisz model.",
    ["From {min} to {max}."] = "Od {min} do {max}.",
    ["Shipped: {value}"] = "Oryginał: {value}",
    ["Rule {n}"] = "Zasada {n}",
    ["Rule {n}, for a speaker with a reply length of its own"] = "Zasada {n}, dla mówcy z własną długością odpowiedzi",
    ["Rule {n}, for Mature content"] = "Zasada {n}, dla treści dla dorosłych",
    ["Move rule {n} up"] = "Zasada {n} w górę",
    ["Move up"] = "W górę",
    ["Move rule {n} down"] = "Przesuń zasadę {n} w dół",
    ["Move down"] = "W dół",
    ["Delete rule {n}"] = "Usuń zasadę {n}",
    ["Other versions of this rule"] = "Inne wersje tej zasady",
    ["Leave a version empty to use the rule text."] = "Zostaw wersję pustą, aby użyć tekstu zasady.",
    ["For a speaker with a reply length of its own"] = "Dla mówcy z własną długością odpowiedzi",
    ["For Mature content"] = "Dla treści dla dorosłych",
    ["Shipped: off"] = "Oryginał: wył.",
    ["Shipped: the mod’s own limit"] = "Oryginał: limit samego moda",
    ["before V’s words"] = "przed słowami V",
    ["after V’s words"] = "po słowach V",
    ["Repeat the “where you are” sentence right before V’s words"] = "Powtórz zdanie „gdzie jesteś” tuż przed słowami V",
    ["The notes for this turn go"] = "Uwagi na tę turę trafiają",
    ["Output rules"] = "Zasady wyjścia",
    ["The numbered rules the model reads before every reply. Use {name} for the character’s name and {words} for the reply length of a speaker that has one."] = "Ponumerowane zasady, które model czyta przed każdą odpowiedzią. Użyj {name} dla imienia postaci, a {words} dla długości odpowiedzi mówcy, który ją ma.",
    ["Example replies"] = "Przykładowe odpowiedzi",
    ["Replies shown to the model after the rules. A small model may copy them word for word, so add none, or keep them short and plain."] = "Odpowiedzi pokazywane modelowi po zasadach. Mały model może skopiować je słowo w słowo, więc nie dodawaj żadnych albo zostaw krótkie i proste.",
    ["Add an example reply"] = "Dodaj przykładową odpowiedź",
    ["An example reply"] = "Przykładowa odpowiedź",
    ["Example reply {n}"] = "Przykładowa odpowiedź {n}",
    ["Opening line"] = "Linia otwierająca",
    ["The first line of the character text. Use {name} for the character’s name."] = "Pierwsza linia tekstu postaci. Użyj {name} dla imienia postaci.",
    ["The last thing the model reads before it answers. Use {name} for the character’s name and {words} for the reply length. The Mature setting adds its own clause after it."] = "Ostatnia rzecz, jaką model czyta przed odpowiedzią. Użyj {name} dla imienia postaci i {words} dla długości odpowiedzi. Ustawienie treści dla dorosłych dodaje po niej własne zdanie.",
    ["Section headings"] = "Nagłówki sekcji",
    ["The headings that mark each part of the prompt. Change the wording, not the order."] = "Nagłówki oznaczające każdą część promptu. Zmieniaj brzmienie, nie kolejność.",
    ["Layout"] = "Układ",
    ["Where some notes go in the prompt."] = "Miejsce, w którym niektóre uwagi trafiają do promptu.",
    ["Sampling"] = "Próbkowanie",
    ["How freely the model words its reply. Leave a box empty to use the shipped value."] = "Jak swobodnie model dobiera słowa w odpowiedzi. Zostaw pole puste, aby użyć wartości oryginalnej.",
    ["Length limits"] = "Limity długości",
    ["Shorten what the model reads, which makes replies faster. The mod’s own limits still apply, so these can only make things shorter."] = "Skracają to, co czyta model, co przyspiesza odpowiedzi. Limity samego moda nadal obowiązują, więc te mogą tylko skracać.",
    ["Stop texts"] = "Teksty stop",
    ["Mature layer"] = "Warstwa dla dorosłych",
    ["The wording added while Mature content is on. The mod picks the explicit or the suggestive version of a line from what the loaded model allows, so edit the version your model uses. An emptied box leaves that line out. The adults-only line and the hard limits are always added last and cannot be edited."] = "Sformułowania dodawane, gdy włączone są treści dla dorosłych. Mod wybiera jawną lub sugerującą wersję wiersza na podstawie tego, na co pozwala załadowany model, więc edytuj wersję, której używa twój model. Pusty kwadrat pomija ten wiersz. Wiersz tylko dla dorosłych i twarde ograniczenia są zawsze dodawane na końcu i nie można ich edytować.",
    ["Speech line"] = "Wiersz mowy",
    ["Word bank"] = "Słownik słów",
    ["Romance line"] = "Wiersz o romansie",
    ["Closing clause"] = "Klauzula zamykająca",
    ["Tone line"] = "Wiersz tonu",
    ["Partner paragraph: affection and desire"] = "Akapit o partnerze: uczucie i pożądanie",
    ["Partner paragraph: nothing invented"] = "Akapit o partnerze: nic nie wymyślać",
    ["{part}, for models that allow explicit sex"] = "{part}, dla modeli, które dopuszczają jawny seks",
    ["{part}, for models that keep sex suggestive"] = "{part}, dla modeli, które zachowują seks w formie sugestii",
    ["This option does not get the Mature layer."] = "Ta opcja nie otrzymuje warstwy dla dorosłych.",
    ["Mature layer and closing line, for models that allow explicit sex"] = "Warstwa dla dorosłych i linia zamykająca, dla modeli, które dopuszczają jawny seks",
    ["Mature layer and closing line, for models that keep sex suggestive"] = "Warstwa dla dorosłych i linia zamykająca, dla modeli, które zachowują seks w formie sugestii",
    ["A reply ends when the model writes one of these. Line breaks count. Up to {max}."] = "Odpowiedź kończy się, gdy model napisze jeden z nich. Podziały wierszy się liczą. Do {max}.",
    ["Add a stop text"] = "Dodaj tekst stop",
    ["A text that ends the reply"] = "Tekst kończący odpowiedź",
    ["Stop text {n}"] = "Tekst stop {n}",
    ["Preview"] = "Podgląd",
    ["The prompt text as the model would read it for a sample character. It follows your edits as you type, before you save."] = "Tekst promptu tak, jak model by go czytał dla przykładowej postaci. Śledzi zmiany podczas pisania, jeszcze przed zapisem.",
    ["Sample character name"] = "Imię przykładowej postaci",
    ["A speaker with a reply length of its own"] = "Mówca z własną długością odpowiedzi",
    ["Reply length in words"] = "Długość odpowiedzi w słowach",
    ["Mature content is on"] = "Treści dla dorosłych wł.",
    ["The preview waits until the problems in the form are fixed."] = "Podgląd czeka, aż problemy w formularzu zostaną naprawione.",
    ["No example replies."] = "Brak przykładów.",
    ["No closing line."] = "Brak linii końcowej.",
    ["Go back to the shipped prompting for {name}? Your changes to this part are removed."] = "Przywrócić oryginalny prompt postaci {name}? Twoje zmiany w tej części zostaną usunięte.",
    ["Go back to the shipped prompting for {name}? All your changes to it are removed."] = "Przywrócić oryginalny prompt postaci {name}? Wszystkie twoje zmiany zostaną usunięte.",
    ["Back to the shipped prompting."] = "Wróć do oryginalnego promptu.",
    ["Prompting"] = "Prompt",
    ["Street reputation"] = "Reputacja na ulicy",
    ["Gangs, the NCPD, corporations and the locals of each district remember what V did: Street Cred, choices in jobs, fights, crimes the police saw and how you treat people. It shapes their greeting, trust and help.\n\nOnly ordinary people, never named or story characters. It changes their words, nothing in the game."] = "Gangi, NCPD, korporacje i mieszkańcy każdej dzielnicy pamiętają, co zrobił V: Street Cred, wybory w zleceniach, walki, przestępstwa widziane przez policję i to, jak traktujesz ludzi. To kształtuje powitanie, zaufanie i pomoc.\n\nTylko zwykli ludzie, nigdy postacie z imieniem ani fabularne. Zmienia ich słowa, nic w grze.",
    ["NPCs react to threats and commands"] = "NPC reagują na groźby i polecenia",
    ["Ordinary people you threaten run, cower or fight back, as their kind would: gang members and guards use their fists for an insult and their weapons for a death threat.\n\nThey may also do what you tell them, if they would: get down, stop, or get out of the vehicle.\n\nOnly ordinary people, never named or story characters, and never during scenes, quests or fights."] = "Zwykli ludzie, którym grozisz, uciekają, kulą się ze strachu albo oddają, zgodnie ze swoją naturą: członkowie gangów i strażnicy biją pięściami za obelgę, a po broń sięgają przy groźbie śmierci.\n\nMogą też zrobić, co im każesz, jeśli by to zrobili: paść na ziemię, zatrzymać się albo wysiąść z pojazdu.\n\nTylko zwykli ludzie, nigdy postacie z imieniem ani z fabuły, i nigdy podczas scen, zadań ani walk.",
    ["Voice language"] = "Język głosu",
    ["English"] = "angielski",
    ["Automatic"] = "Auto",
    ["Polish"] = "polski",
    ["Russian"] = "rosyjski",
    ["Ukrainian"] = "ukraiński",
    ["Turkish"] = "turecki",
    ["Czech"] = "czeski",
    ["Hungarian"] = "węgierski",
    ["Japanese"] = "japoński",
    ["Korean"] = "koreański",
    ["Chinese"] = "chiński",
    ["Choose one of the listed reply languages."] = "Wybierz jeden z wymienionych języków odpowiedzi.",
    ["No speech was heard. Hold the talk key while you speak."] = "Nie wykryto mowy. Przytrzymaj klawisz głosowy, kiedy mówisz.",
    ["Voice activation"] = "Aktywacja głosem",
    ["Voice activation could not open the microphone. Check your Windows input device."] = "Aktywacja głosem nie mogła otworzyć mikrofonu. Sprawdź urządzenie wejściowe w systemie Windows.",
    ["Voice input could not reach Convai. Hold the voice key again, or type."] = "Wejście głosowe nie mogło połączyć się z Convai. Przytrzymaj ponownie klawisz głosowy lub wpisz tekst.",
    ["Talk without a key. While you face a character or a companion is near, the mod listens and answers when you pause for about a second.\n\nNever during the game’s own scenes or choices, or while a character speaks. Nothing leaves your PC unless speech is heard. Headphones work best, but a Bluetooth headset’s microphone drops it to call quality while this listens."] = "Mów bez przytrzymywania klawisza. Gdy stoisz twarzą do postaci albo w pobliżu jest towarzysz, mod nasłuchuje i odpowiada, gdy zrobisz pauzę mniej więcej na sekundę.\n\nNigdy podczas scen gry ani wyboru kwestii dialogowych i nigdy, gdy postać mówi. Nic nie opuszcza twojego PC, dopóki nie zostanie usłyszana mowa. Najlepiej słuchawki, ale mikrofon zestawu Bluetooth przełącza na jakość rozmowy podczas nasłuchu.",
    ["Opening microphone…"] = "Otwieranie mikrofonu…",
    ["Speak now"] = "Mów teraz",
    ["Type in the search box to find a model by name or record, for example “rita wheeler”. A part of a word is enough."] = "Wpisz tekst w polu wyszukiwania, aby znaleźć model po nazwie lub rekordzie, na przykład „rita wheeler”. Wystarczy fragment słowa.",
    ["Content packs"] = "Pakiety treści",
    ["Add-ons that change how the characters talk."] = "Dodatki zmieniające sposób mówienia postaci.",
    ["Content packs add rules after yours. You cannot edit them here: turn a pack off under Settings > Content packs in the game."] = "Pakiety treści dodają zasady po Twoich. Nie możesz ich tu edytować: wyłącz pakiet w grze w Ustawienia > Pakiety treści.",
    ["From the content pack {name}"] = "Z pakietu treści {name}",
    ["Content packs that change this prompt: {names}. Your own changes stay on top of theirs, and Reset to default goes back to the pack’s wording."] = "Pakiety treści zmieniające ten prompt: {names}. Twoje zmiany zostają ponad ich zmianami, a Przywróć domyślne wraca do brzmienia pakietu.",
    ["Memory in use"] = "Używana pamięć",
    ["Normal memory"] = "Zwykła pamięć",
    ["Forget memories clears only the memory shown here. The other memory stays as it is."] = "Zapomnij wspomnienia czyści tylko pamięć pokazaną tutaj. Druga pamięć pozostaje bez zmian.",
    ["This clears the memory in use: {memory}."] = "To czyści używaną pamięć: {memory}.",
    ["Backspace"] = "Backspace",
    ["Cancelled."] = "Anulowano.",
    ["Caps lock"] = "Caps Lock",
    ["Choose a key or a controller button."] = "Wybierz klawisz lub przycisk pada.",
    ["Choose the keys and controller buttons for talking by voice or text, the group chats and the Companion Manager. They work at once."] = "Wybierz klawisze i przyciski pada do rozmów głosowych i tekstowych, czatów grupowych oraz Menedżera towarzyszy. Działają od razu.",
    ["Choose the keys and controller buttons for the mod’s actions. Press Set, then the key or button you want. Esc or B cancels. A change works at once, and the keys you set in Cyber Engine Tweaks keep working. Pick keys the game does not already use."] = "Wybierz klawisze i przyciski pada do działań moda. Naciśnij Ustaw, a potem wybrany klawisz lub przycisk. Esc lub B anuluje. Zmiana działa od razu, a klawisze ustawione w Cyber Engine Tweaks nadal działają. Wybieraj klawisze, których gra jeszcze nie używa.",
    ["Controller {button}"] = "Pad {button}",
    ["D-pad down"] = "Krzyżak w dół",
    ["D-pad left"] = "Krzyżak w lewo",
    ["D-pad right"] = "Krzyżak w prawo",
    ["D-pad up"] = "Krzyżak w górę",
    ["Down arrow"] = "Strzałka w dół",
    ["End"] = "End",
    ["Enter"] = "Enter",
    ["Group text chat"] = "Czat grupowy tekstowy",
    ["Group voice chat"] = "Czat grupowy głosowy",
    ["Hold it to talk to the characters around you at once, and let go to send. Facing nobody, you talk to the first member of your party and two others from it."] = "Przytrzymaj, aby mówić naraz do wszystkich postaci wokół ciebie, a puść, aby wysłać. Gdy na nikogo nie patrzysz, rozmawiasz z pierwszym członkiem drużyny i dwoma innymi członkami drużyny.",
    ["Hold it to talk to Johnny, the voice in your head, wherever you face, and let go to send. It needs Johnny in your head turned on in Settings."] = "Przytrzymaj, aby rozmawiać z Johnnym, głosem w twojej głowie, gdziekolwiek patrzysz, a puść, aby wysłać. Wymaga włączenia opcji Johnny w twojej głowie w Ustawieniach.",
    ["Hold the key or button while you speak and let go to send, like the Cyber Engine Tweaks talk key. Facing nobody, you talk to the first member of your party."] = "Przytrzymaj klawisz lub przycisk podczas mówienia i puść, aby wysłać, tak jak klawisz rozmowy w Cyber Engine Tweaks. Gdy na nikogo nie patrzysz, rozmawiasz z pierwszym członkiem drużyny.",
    ["Home"] = "Home",
    ["Insert"] = "Insert",
    ["Key bindings"] = "Przypisania klawiszy",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "Przypisania klawiszy wymagają Codeware, a tej gry go nie ma. Otwórz Pomoc, aby sprawdzić, czego brakuje.",
    ["Key or button"] = "Klawisz lub przycisk",
    ["Left arrow"] = "Strzałka w lewo",
    ["Menu"] = "Menu",
    ["No key was pressed, so nothing changed."] = "Nie naciśnięto klawisza, więc nic się nie zmieniło.",
    ["Not available"] = "Niedostępne",
    ["Not set"] = "Nieustawione",
    ["Num lock"] = "Num Lock",
    ["Page down"] = "Page Down",
    ["Page up"] = "Page Up",
    ["Pause"] = "Pause",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "Naciśnij go, a potem klawisz lub przycisk pada, który chcesz. Esc lub B anuluje. Działa od razu.",
    ["Press it to open the Companion Manager while you play."] = "Naciśnij, aby otworzyć Menedżera towarzyszy podczas gry.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "Naciśnij, aby pisać do postaci, która jest przed tobą. Gdy na nikogo nie patrzysz, piszesz do pierwszego członka drużyny.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "Naciśnij, aby pisać do Johnny'ego, głosu w twojej głowie, gdziekolwiek patrzysz. Wymaga włączenia opcji Johnny w twojej głowie w Ustawieniach.",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "Naciśnij, aby pisać naraz do wszystkich postaci wokół ciebie. Gdy na nikogo nie patrzysz, piszesz do pierwszego członka drużyny i dwóch innych członków.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "Naciśnij klawisz lub przycisk pada dla: {action}. Esc lub B anuluje.",
    ["Print screen"] = "Print Screen",
    ["Remove the key or button you set here."] = "Usuń klawisz lub przycisk ustawiony tutaj.",
    ["Right arrow"] = "Strzałka w prawo",
    ["Scroll lock"] = "Scroll Lock",
    ["Space"] = "Spacja",
    ["Tab"] = "Tab",
    ["Talk by text"] = "Rozmowa tekstowa",
    ["Talk by voice"] = "Rozmowa głosowa",
    ["Talk to Johnny by text"] = "Rozmowa z Johnnym tekstem",
    ["Talk to Johnny by voice"] = "Rozmowa z Johnnym głosem",
    ["That key is already used for another action."] = "Ten klawisz jest już używany do innej czynności.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "Nie udało się wczytać przypisań klawiszy moda. Otwórz Pomoc, aby zobaczyć, co jest nie tak.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "Skrypty moda się nie wczytały, więc nie można ustawić żadnego klawisza. Otwórz Pomoc, aby zobaczyć, co jest nie tak.",
    ["Up arrow"] = "Strzałka w górę",
    ["View"] = "Widok",
    ["{action} cleared."] = "Usunięto przypisanie: {action}.",
    ["{action} is set to {key}."] = "{action} ustawiono na {key}.",
    ["{key} is already used for {other}. Choose another."] = "{key} jest już użyty dla: {other}. Wybierz inny.",
    ["10 minutes"] = "10 minut",
    ["2 minutes"] = "2 minuty",
    ["5 minutes"] = "5 minut",
    ["Cancel this meeting. She is not told."] = "Odwołaj spotkanie. Nie dowie się.",
    ["Car"] = "Autem",
    ["Choose how long she waits."] = "Wybierz, jak długo ma czekać.",
    ["Choose how she arrives."] = "Wybierz, jak przyjedzie.",
    ["Choose one of the listed options."] = "Wybierz jedną z podanych opcji.",
    ["Choose when she arrives."] = "Wybierz, kiedy przyjedzie.",
    ["Companions travel to you when you invite them: they walk or drive in, text you, wait, and remember if you never come.\n\nOff by default."] = "Towarzysze przychodzą, gdy ich zaprosisz: pieszo lub autem, piszą, czekają i pamiętają, jeśli nigdy nie przyjdziesz.\n\nDomyślnie wyłączone.",
    ["Fine. Call me when you know what you want."] = "Dobra. Zadzwoń, jak będziesz wiedzieć, czego chcesz.",
    ["How long she waits"] = "Jak długo ona czeka",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "Jak długo będzie czekać na ciebie po przybyciu, teraz. Po przybyciu o określonej porze czeka tyle, ile wybrane opóźnienie. Czekanie zatrzymuje się w walce, scenie lub menu.",
    ["How she arrives"] = "Jak przyjeżdża",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "Czekałam {minutes} minut w {place}, a ciebie nigdy nie było. Zapomnij.",
    ["I'm here at {place}. Where are you?"] = "Jestem na {place}. Gdzie jesteś?",
    ["Immersive invitations"] = "Immersyjne zaproszenia",
    ["In 10 minutes"] = "Za 10 minut",
    ["In 2 minutes"] = "Za 2 minuty",
    ["In 5 minutes"] = "Za 5 minut",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "Zaproś towarzysza, a ona naprawdę przyjdzie: pojawi się poza zasięgiem wzroku, przyjdzie pieszo lub autem, napisze, gdy będzie na miejscu, i będzie czekać.",
    ["Meet at my waypoint when I ask"] = "Przyjdź do mojego znacznika na prośbę",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "Wyłączone: Zaproś sprowadza towarzysza od razu do twojego boku.\n\nWłączone: towarzysz, którego zaprosisz przyciskiem Zaproś, w karcie Kontakty lub wiadomością, przyjeżdża do ciebie i pojawia się po czasie wybranym tutaj. Pisze, gdy jest na miejscu, czeka, a jeśli nigdy nie przyjdziesz, odchodzi zły (i to pamięta).",
    ["Right now"] = "Teraz",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "Teraz: rusza, gdy tylko będzie gotowa.\n\nZa 2, 5 lub 10 minut: prawdziwe minuty gry, więc przyjeżdża o tej porze. Potem czeka tyle, ile to opóźnienie.",
    ["She texts you"] = "Pisze do ciebie",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "Pisze, gdy przyjedzie, gdy odwołasz i gdy da za wygraną. Wyłączone: bez wiadomości (i tak pamięta, że ją wystawiono).",
    ["Something came up and I can't make it. Sorry."] = "Coś mi wypadło i nie dam rady. Sorki.",
    ["Walk"] = "Pieszo",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "Pieszo: pojawia się poza twoim zasięgiem wzroku i podchodzi do ciebie.\n\nAutem: gdy w pobliżu jest droga, podjeżdża, staje na drodze, wysiada i resztę idzie pieszo. Bez drogi idzie pieszo. Auto zostaje w pobliżu na przejażdżkę i znika, gdy opuści twoją grupę albo oddalicie się od niego.",
    ["When she arrives"] = "Gdy przyjedzie",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "Gdy poprosisz ją, by przyszła do twojego znacznika, a na mapie jest pinezka, idzie tam i to mówi. Wyłączone: zawsze przychodzi tam, gdzie jesteś.",
    ["Your position cannot be read yet."] = "Nie można jeszcze odczytać twojej pozycji.",
    ["on her way"] = "w drodze",
    ["the meeting spot"] = "miejsce spotkania",
    ["waiting at {place}"] = "czeka w {place}",
    ["{name} is already on the way."] = "{name} jest już w drodze.",
    ["{name} is on her way."] = "{name} jest w drodze.",
    ["{name} is on her way. About {minutes} minutes."] = "{name} jest w drodze. Około {minutes} minut.",
    ["{name} · {state}"] = "{name} · {state}",
    ["{name}: Good to see you. Let us go."] = "{name}: Miło cię widzieć. Ruszajmy.",
    ["Corpo Plaza"] = "Corpo Plaza",
    ["Heywood Glen"] = "Heywood Glen",
    ["Megabuilding H10"] = "Megabuilding H10",
    ["Move out"] = "Niech się wyprowadzi",
    ["That companion is not available."] = "Ten towarzysz jest niedostępny.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "Nie masz tego mieszkania.",
    ["at home"] = "w domu",
    ["out"] = "poza domem",
    ["with you"] = "z tobą",
    ["{count} more housemates"] = "{count} więcej współlokatorów",
    ["{name} has moved out."] = "{name} już u ciebie nie mieszka.",
    ["{name} is back at home."] = "{name} jest znów w domu.",
    ["{name} joins you."] = "{name} dołącza do ciebie.",
    ["{name} moves into {apartment}."] = "{name} wprowadza się do {apartment}.",
    ["{name} now lives in {apartment} and stays in your party until sent home."] = "{name} mieszka teraz w {apartment} i zostaje w twojej grupie, dopóki nie wróci do domu.",
    ["{name} stops living at your place. She stays as she is otherwise."] = "{name} już u ciebie nie mieszka. Poza tym bez zmian.",
    ["{name} · lives in {apartment} · {state}"] = "{name} · mieszka w {apartment} · {state}",
    ["Companions change outfits"] = "Towarzysze zmieniają stroje",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s own copies, never the game’s own characters. Turning this off keeps what they wear now."] = "Towarzysze z twojej drużyny co jakiś czas zmieniają stroje: inny wygląd w dzień i inny w nocy oraz codzienne ubrania w domu, jeśli postać je ma.\n\nTylko poza twoim polem widzenia, nigdy na twoich oczach, i tylko w przypadku własnych kopii twojej drużyny, nigdy postaci z gry. Wyłączenie tej opcji sprawia, że zostają w tym, co mają na sobie w danym momencie.",
    ["Choose how often companions speak up."] = "Wybierz, jak często towarzysze się odzywają.",
    ["Companions speak up"] = "Towarzysze się odzywają",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example. Also what V visibly wears while an Equipment-EX outfit is on, so characters describe the outfit and not the clothes it hides.\n\nOff by default. Off: it is not sent, and nothing is read from those mods."] = "Jak V się czuje według innych modów, jeśli są zainstalowane: na przykład zmęczenie, głód, pragnienie, nerwy i uzależnienia z Dark Future. Także to, co V widocznie ma na sobie, gdy aktywny jest strój z Equipment-EX, by postacie opisywały ten strój, a nie ukryte pod nim ubrania.\n\nDomyślnie wyłączone. Wyłączone: nic nie jest wysyłane i z tych modów nic nie jest odczytywane.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "Ile czasu minęło od ostatniej rozmowy V z tą postacią, w grze i w prawdziwych dniach: od ostatniej nocy albo od kilku dni. Mówi się o tym tylko wtedy, gdy przerwa jest na tyle długa, by miała znaczenie, i nie powtarza się tego w tej samej rozmowie.\n\nWyłączone: nic nie jest wysyłane, a mod przestaje odczytywać zegar gry dla tej informacji.",
    ["Music and TV"] = "Muzyka i TV",
    ["Other mods’ state"] = "Stan innych modów",
    ["Speaks up normally"] = "Odzywa się normalnie",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Piosenka z radia w samochodzie, gdy V jedzie z postacią, albo z kieszonkowego radia V, oraz to, co leci w telewizorze w pobliżu V.\n\nWyłączone: nic nie jest wysyłane, a mod przestaje to odczytywać z gry.",
    ["Time since last talk"] = "Czas od ostatniej rozmowy",
    ["Companions in your party sometimes start talking on their own, at a calm moment or after a scene. With two or more near you, it is often a short chat between up to three of them, and you can join in by talking. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often (the default): about 6.\n\nWith Johnny speaking up too, the rates add up and they take turns."] = "Towarzysze czasem sami zaczynają mówić: w spokojnej chwili lub po scenie. Gdy w pobliżu są dwaj lub więcej, zwykle to krótka rozmowa między najwyżej trzema, w którą można się włączyć. Nigdy podczas walk, scen, połączeń czy w menu.\n\nRzadko: około 2 na godzinę gry. Normalnie: około 4. Często (domyślnie): około 6.\n\nGdy odzywa się także Johnny, obie częstotliwości się sumują, a odzywający się mówią na zmianę.",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there. Give Talk to Johnny a key on the Key bindings page: none is set by default.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "Johnny Silverhand odpowiada na klawisze „Rozmowa z Johnnym“ jako głos w głowie V, gdy fabuła go tam umieści. Przypisz klawisz do „Rozmowa z Johnnym“ na stronie Przypisania klawiszy: domyślnie nie ma żadnego.\n\nWłączone: odpowiada, gdy się do niego mówi. Rzadko: odzywa się sam, około 2 razy na godzinę. Normalnie: około 4. Często: około 6.\n\nGdy odzywają się także towarzysze, częstotliwości się sumują i mówią na zmianę.",
    ["Choose which live game info the characters are told, such as location, time, weather, company, health, money, gear, quests, music and TV, and other mods’ state.\n\nAll on by default except other mods’ state, which is off. An off kind is not sent to any conversation provider."] = "Wybierz, które informacje o grze na żywo mają być przekazywane postaciom, na przykład miejsce, czas, pogodę, towarzyszy, zdrowie, pieniądze, ekwipunek, zadania, muzykę i TV oraz stan innych modów.\n\nDomyślnie wszystko jest włączone oprócz stanu innych modów, który jest wyłączony. Wyłączony rodzaj nie jest wysyłany żadnemu dostawcy rozmów.",
    ["Housemates"] = "Współlokatorzy",
    ["Housemates talk to each other"] = "Współlokatorzy rozmawiają ze sobą",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "Gdy dwoje lub więcej współlokatorów jest z tobą w domu, od czasu do czasu rozmawiają ze sobą.",
    ["Characters you tell they can stay at your place move into your apartments and live there."] = "Postacie, którym powiesz, że mogą zostać u ciebie, wprowadzają się do twoich mieszkań i tam mieszkają.",
    ["Characters you tell they can stay at your place move into your apartments and live there.\n\nOff by default."] = "Postacie, którym powiesz, że mogą zostać u ciebie, wprowadzają się do twoich mieszkań i tam mieszkają.\n\nDomyślnie wyłączone.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "Włączone: postacie, którym powiesz, że mogą zostać u ciebie, wprowadzają się do twoich mieszkań i tam mieszkają, a możesz zabrać je ze sobą.\n\nWyłączone: nic z tego nie działa. Po wyłączeniu wyprowadzają się z twoich mieszkań, ale zostaje zapamiętane, kto tam mieszkał, więc po ponownym włączeniu wracają.",
    ["OmniVoice Python"] = "OmniVoice Python",
    ["OmniVoice’s code could not load in it"] = "kod OmniVoice nie mógł się załadować",
    ["PyTorch is not installed in it"] = "PyTorch nie jest w nim zainstalowany",
    ["Your own Python (omni-python.txt) is being tested. Open this page again in a minute."] = "Twój własny Python (omni-python.txt) jest testowany. Otwórz tę stronę ponownie za minutę.",
    ["Your own Python (omni-python.txt) is tested when OmniVoice starts or when this page checks again."] = "Twój własny Python (omni-python.txt) jest testowany, gdy OmniVoice się uruchamia lub gdy ta strona ponownie sprawdza.",
    ["Your own Python (omni-python.txt) runs OmniVoice with {backend} on {card}. Experimental."] = "Twój własny Python (omni-python.txt) uruchamia OmniVoice z {backend} na {card}. Eksperymentalne.",
    ["Your own Python (omni-python.txt) was not used: {reason}. OmniVoice uses the Runtime’s Python, which needs an NVIDIA card."] = "Twój własny Python (omni-python.txt) nie został użyty: {reason}. OmniVoice używa Python'a z Runtime, który wymaga karty NVIDIA.",
    ["a test on the graphics card failed"] = "test na karcie graficznej nie powiódł się",
    ["it did not start or did not answer in time"] = "nie uruchomił się lub nie odpowiedział w porę",
    ["its PyTorch finds no graphics card (no CUDA or ROCm)"] = "jego PyTorch nie znalazł karty graficznej (bez CUDA czy ROCm)",
    ["the OmniVoice pack is not installed"] = "pakiet OmniVoice nie jest zainstalowany",
    ["the file does not name a python.exe that exists"] = "plik nie wskazuje istniejącego python.exe",
    ["the module {module} is missing in it"] = "moduł {module} w nim nie istnieje",
    ["1 minute"] = "1 minuta",
    ["2 people"] = "2 osoby",
    ["3 people"] = "3 osoby",
    ["4 people"] = "4 osoby",
    ["Every character who lives at your place moves out at once, from every apartment. Party members who do not live there are not touched. A housemate who is with you stays in your party."] = "Wszystkie postacie, które u ciebie mieszkają, wyprowadzają się jednocześnie, z każdego mieszkania. Członkowie drużyny, którzy tam nie mieszkają, nie są dotknięci. Współlokator, który jest z tobą, pozostaje w twojej drużynie.",
    ["Evict"] = "Niech się wyprowadzi",
    ["Evict all housemates"] = "Niech się wyprowadzą wszyscy współlokatorzy",
    ["Housemates in one chat"] = "Współlokatorzy w jednym czacie",
    ["Housemates moved out: {count}"] = "Współlokatorzy się wyprowadzili: {count}",
    ["How long the housemates stay quiet after a chat before they may start another. The Companions speak up setting still limits how many chats come in an hour."] = "Jak długo współlokatorzy są cicho po czacie, zanim mogą zacząć kolejny. Ustawienie Towarzysze się odzywają wciąż ogranicza, ile czatów przychodzi na godzinę.",
    ["How many housemates join one chat when that many are home near each other. They speak one at a time. With fewer at home, the chat is as big as it can be."] = "Ile współlokatorów bierze udział w jednym czacie, gdy tyle osób jest w domu obok siebie. Mówią jeden na raz. Z mniej w domu, czat jest tak duży, jak to możliwe.",
    ["Move-in apartment"] = "Mieszkanie do wprowadzenia",
    ["Nobody lives at your place."] = "Nikt nie mieszka u ciebie.",
    ["Pause between chats"] = "Przerwa między czatami",
    ["Where a character moves in when you say she can stay but name no apartment and you are not standing in one of yours.\n\nAsk me: she asks which one. Otherwise she takes the apartment you pick here. Only the apartments you own are listed."] = "Gdzie postać się wprowadza, kiedy mówisz, że może zostać, ale nie podajesz nazwy mieszkania i nie stoisz w jednym ze swoich.\n\nPytaj mnie: Ona pyta, które. Inaczej bierze mieszkanie, które tutaj wybierzesz. Wypisane są tylko mieszkania, które posiadasz.",
    ["Ask me"] = "Pytaj mnie",
    ["Could not start"] = "Nie udało się uruchomić",
    ["Did not start"] = "Nie uruchomiło się",
    ["If the folder is there, the newest log in red4ext/logs says why RED4ext did not load it: an antivirus that removed a file, or a missing Visual C++ runtime."] = "Jeśli folder jest, najnowszy log w red4ext/logs wyjaśni, dlaczego RED4ext go nie wczytał: antywirus usunął plik albo brakuje Visual C++ runtime.",
    ["Load a save first. A key can be set only while a game is loaded."] = "Najpierw wczytaj zapis. Klawisz można ustawić tylko przy wczytanej grze.",
    ["No key press reached the mod, so nothing changed. If keys do not arrive from this menu, set the key in Cyber Engine Tweaks’ Bindings: it works the same."] = "Do moda nie dotarło żadne naciśnięcie klawisza, więc nic się nie zmieniło. Jeśli klawisze nie docierają z tego menu, ustaw klawisz w przypisaniach Cyber Engine Tweaks: działa to tak samo.",
    ["Runtime incomplete"] = "Runtime niekompletny",
    ["Runtime not loaded"] = "Runtime nie wczytany",
    ["Service not running ({reason})"] = "Usługa nie działa ({reason})",
    ["The Runtime’s plugin is loaded, but the conversation service left no trace in this session. launcher.log in red4ext/plugins/AiNpcCyberpunkCode says why: launcher.ini switched off, Node missing, or Node blocked by a security program. Fix that, then restart the game."] = "Plugin Runtime jest wczytany, ale usługa rozmów nie zostawiła śladu w tej sesji. Przyczynę podaje launcher.log w red4ext/plugins/AiNpcCyberpunkCode: launcher.ini wyłączony, brak Node albo Node zablokowany przez program zabezpieczający. Napraw to, a potem zrestartuj grę.",
    ["The conversation service cannot see this mod’s folder in the game: a mod manager’s virtual folders, or a folder it may not read. Extract the Runtime straight into the Cyberpunk 2077 folder, or start the game from the mod manager that holds the Runtime."] = "Usługa rozmów nie widzi folderu tego moda w grze: wirtualne foldery menedżera modów albo folder, którego nie może odczytać. Rozpakuj Runtime bezpośrednio do folderu Cyberpunk 2077 albo uruchom grę z menedżera modów, w którym jest Runtime.",
    ["The conversation service was started and never reported back. A security program probably stopped it at once, or Node cannot run on this PC. Allow red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in your security program, then restart the game."] = "Usługa rozmów została uruchomiona, ale nigdy nie odpowiedziała. Prawdopodobnie program zabezpieczający od razu ją zatrzymał albo Node nie może działać na tym komputerze. Zezwól na red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe w programie zabezpieczającym, a potem zrestartuj grę.",
    ["Windows would not let the game start the conversation service (error {error}). A security program may be blocking node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: allow it, then restart the game."] = "Windows nie pozwolił grze uruchomić usługi rozmów (błąd {error}). Program zabezpieczający może blokować node.exe w red4ext/plugins/AiNpcCyberpunkMod/app/node: zezwól na to, a potem zrestartuj grę.",
    ["Add a server address first."] = "Najpierw dodaj adres serwera.",
    ["Asks the server three times who it is and shows whether it is reachable, how long it takes to answer and its version. It sends no speech."] = "Trzykrotnie pyta serwer, kim jest, i pokazuje, czy jest osiągalny, jak długo odpowiada i jaka ma wersję. Nie wysyła mowy.",
    ["Connected. The server speaks with {voice}."] = "Połączono. Serwer mówi głosem {voice}.",
    ["Custom voices"] = "Własne głosy",
    ["Deletes the saved server address. Remote OmniVoice needs one to speak."] = "Usuwa zapisany adres serwera. Zdalny OmniVoice potrzebuje go, aby mówić.",
    ["It answers in {ms} ms."] = "Odpowiada w {ms} ms.",
    ["Its voice runs on {device}."] = "Jego głos działa na {device}.",
    ["Loading"] = "Wczytywanie",
    ["Not connected. Replies show as text until the server answers."] = "Brak połączenia. Odpowiedzi są pokazywane jako tekst, dopóki serwer nie odpowie.",
    ["Nothing answered at that address. Check that the server is running, that the address and port are right and that both PCs are on the same network. A server started with its default only listens on its own PC: start it with the listen address 0.0.0.0."] = "Pod tym adresem nikt nie odpowiedział. Sprawdź, czy serwer działa, czy adres i port są poprawne i czy oba komputery są w tej samej sieci. Serwer uruchomiony z ustawieniami domyślnymi nasłuchuje tylko na swoim komputerze: uruchom go z adresem nasłuchu 0.0.0.0.",
    ["Off. OmniVoice runs on this PC."] = "Wyłączony. OmniVoice działa na tym komputerze.",
    ["On, but no server address is saved. OmniVoice cannot speak yet."] = "Włączony, ale nie zapisano adresu serwera. OmniVoice jeszcze nie może mówić.",
    ["On, but no server address is saved. Pocket is used until you add one."] = "Włączony, ale nie zapisano adresu serwera. Dopóki go nie dodasz, używany jest Pocket.",
    ["On, but no server address is saved. The server is not used yet."] = "Włączony, ale nie zapisano adresu serwera. Serwer nie jest jeszcze używany.",
    ["On, but a cloud voice is chosen under Companion voices, so the server is not used."] = "Włączony, ale w polu Głosy towarzyszy wybrano głos chmurowy, więc serwer nie jest używany.",
    ["On. Waiting for the conversation service."] = "Włączony. Oczekiwanie na usługę rozmów.",
    ["Paste address"] = "Wklej adres",
    ["Remote OmniVoice"] = "Zdalny OmniVoice",
    ["Render the voices on another PC or graphics card that runs the OmniVoice server, so this PC keeps its frames.\n\nTurn it on, press Apply and add the server address below. The server then speaks for every Pocket or OmniVoice choice under Companion voices; a cloud voice stays as chosen. If it cannot be reached, replies show as text and the mod retries every few seconds."] = "Renderuj głosy na innym komputerze lub karcie graficznej z serwerem OmniVoice, aby ten komputer zachował płynność.\n\nWłącz, naciśnij Zastosuj i dodaj poniżej adres serwera. Serwer mówi wtedy za każdy wybór Pocket lub OmniVoice w polu Głosy towarzyszy; głos chmurowy zostaje wybrany tak, jak był. Gdy serwera nie można osiągnąć, odpowiedzi są pokazywane jako tekst, a mod ponawia próbę co kilka sekund.",
    ["Render the OmniVoice voices on another PC or graphics card that runs the OmniVoice server."] = "Renderuj głosy OmniVoice na innym komputerze lub karcie graficznej, na którym działa serwer OmniVoice.",
    ["Render Pocket and OmniVoice voices on another PC or graphics card: the on/off switch, the server address and a connection test. It works whichever of those voices is chosen above."] = "Renderuj głosy Pocket i OmniVoice na innym komputerze lub karcie graficznej: przełącznik włączania/wyłączania, adres serwera i test połączenia. Działa niezależnie od tego, który z nich jest wybrany powyżej.",
    ["Server address"] = "Adres serwera",
    ["Something answered, but it is not the OmniVoice server. Check the port."] = "Coś odpowiedziało, ale to nie jest serwer OmniVoice. Sprawdź port.",
    ["Start the OmniVoice server on the other PC. Its window shows the address to use, for example 192.168.1.20:8765. Copy it, then choose Paste address. It is read from the clipboard once and saved on this computer.\n\nOn the same PC use 127.0.0.1:8765. You can also write address=192.168.1.20:8765 in player-remote-omnivoice.txt in the conversation service folder.\n\nNothing is sent to it until Remote OmniVoice is on and OmniVoice is chosen, or you press Test."] = "Uruchom serwer OmniVoice na drugim komputerze. Jego okno pokazuje adres do użycia, na przykład 192.168.1.20:8765. Skopiuj go, a następnie wybierz Wklej adres. Adres jest odczytywany ze schowka raz i zapisywany na tym komputerze.\n\nNa tym samym komputerze użyj 127.0.0.1:8765. Możesz też wpisać address=192.168.1.20:8765 w pliku player-remote-omnivoice.txt w folderze usługi rozmów.\n\nNic nie jest wysyłane, dopóki Zdalny OmniVoice nie jest włączony i nie wybrano OmniVoice, albo dopóki nie naciśniesz Testuj.",
    ["Status"] = "Stan",
    ["The OmniVoice server cannot be reached. Replies show as text until it answers. The mod asks it again every few seconds."] = "Nie można połączyć się z serwerem OmniVoice. Odpowiedzi są pokazywane jako tekst, dopóki serwer nie odpowie. Mod ponawia próbę co kilka sekund.",
    ["The clipboard does not hold a server address."] = "Schowek nie zawiera adresu serwera.",
    ["The clipboard is empty. Copy the address first."] = "Schowek jest pusty. Najpierw skopiuj adres.",
    ["The port must be a number from 1 to 65535."] = "Port musi być liczbą od 1 do 65535.",
    ["The server address was removed."] = "Adres serwera został usunięty.",
    ["The server answered but could not load its voice. Its window says why."] = "Serwer odpowiedział, ale nie mógł wczytać swojego głosu. Jego okno podaje powód.",
    ["The server answered but is still loading its voice. Try again in a minute."] = "Serwer odpowiedział, ale nadal wczytuje swój głos. Spróbuj ponownie za minutę.",
    ["The server is another version. Use the server folder and the mod from the same release."] = "Serwer ma inną wersję. Użyj folderu serwera i moda z tej samej wersji.",
    ["The server is ready."] = "Serwer jest gotowy.",
    ["The server refused the request."] = "Serwer odrzucił żądanie.",
    ["The server took too long to answer."] = "Serwer odpowiadał zbyt długo.",
    ["Use the address only: no user name, no path, no #."] = "Podaj tylko adres: bez nazwy użytkownika, bez ścieżki i bez #.",
    ["Use the address the server window shows, such as 192.168.1.20:8765, without https://."] = "Podaj adres pokazany w oknie serwera, na przykład 192.168.1.20:8765, bez https://.",
    ["Waiting for the server to answer…"] = "Oczekiwanie na odpowiedź serwera…",
    ["Whether the server is in use right now. It is checked when a voice is needed and again every few seconds after a failure, never while you play."] = "Czy serwer jest teraz w użyciu. Sprawdzane, gdy potrzebny jest głos, i ponownie co kilka sekund po błędzie, nigdy podczas gry.",
    ["Your own character, made in the character editor."] = "Twoja własna postać, stworzona w edytorze postaci.",
    ["Build for your game"] = "Wersja pod twoją grę",
    ["Your game is {game} but the Runtime is the one for game {runtime}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over this one, then restart the game."] = "Twoja gra to {game}, ale Runtime jest dla gry {runtime}. Pobierz pełny zip instalacyjny dla gry {game} ze strony moda na Nexus Mods (plik główny dla gry 2.5, opcjonalny plik dla gry 2.31), rozpakuj go do folderu Cyberpunk 2077 nad obecnymi plikami i zrestartuj grę.",
    ["Your game is {game} but the Scripts are the build for game {scripts}. Get the update zip for game {game} from the mod’s Nexus Mods page (the update file is for game 2.5, the optional update file for game 2.31) and install it over these, then restart the game."] = "Twoja gra to {game}, ale Scripts to build dla gry {scripts}. Pobierz zip z aktualizacją dla gry {game} ze strony moda na Nexus Mods (plik aktualizacji dla gry 2.5, opcjonalny plik aktualizacji dla gry 2.31), zainstaluj go nad obecnymi plikami i zrestartuj grę.",
    ["Your game is {game} but the Scripts and the Runtime are the build for game {scripts}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over these, then restart the game."] = "Twoja gra to {game}, ale Scripts i Runtime są dla gry {scripts}. Pobierz pełny zip instalacyjny dla gry {game} ze strony moda na Nexus Mods (plik główny dla gry 2.5, opcjonalny plik dla gry 2.31), rozpakuj go do folderu Cyberpunk 2077 nad obecnymi plikami i zrestartuj grę.",
    ["The Scripts are the build for game {scripts} but the Runtime is the build for game {runtime}, and the game version matches neither. Extract the full install zip made for the same game as yours (from Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Scripts to build dla gry {scripts}, a Runtime to build dla gry {runtime}, i wersja gry nie pasuje do żadnego z nich. Rozpakuj do folderu Cyberpunk 2077 pełny zip instalacyjny przygotowany dla tej samej gry co Twoja (z Nexus Mods), a potem zrestartuj grę.",
    ["The Runtime is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Runtime jest dla gry {other}, Twoja to {game}. Pobierz pełny zip dla {game}.",
    ["The Scripts are for game {other}, yours is {game}. Get the update zip for {game}."] = "Scripts są dla gry {other}, Twoja to {game}. Pobierz Update-ZIP dla {game}.",
    ["This mod is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Mod jest dla gry {other}, Twoja to {game}. Pobierz pełny zip dla {game}.",
    ["Scripts are for game {scripts}, Runtime for {runtime}. They must match. See Help in Settings."] = "Scripts są dla gry {scripts}, Runtime dla {runtime}. Muszą pasować. Pomoc w Ustawieniach.",
    ["Choose one of the listed microphones."] = "Wybierz jeden z wymienionych mikrofonów.",
    ["Microphone"] = "Mikrofon",
    ["The microphone you chose in Settings ({chosen}) is not connected, so the Windows default input is used: {name}."] = "Mikrofon wybrany w Ustawieniach ({chosen}) nie jest podłączony, więc używane jest domyślne wejście Windows: {name}.",
    ["The microphone you chose in Settings is not connected, so the Windows default input is used."] = "Mikrofon wybrany w Ustawieniach nie jest podłączony, więc używane jest domyślne wejście Windows.",
    ["Windows default"] = "Domyślne Windows",
    ["not connected"] = "niepodłączony",
    ["{name}, chosen in Settings > Voices."] = "{name}, wybrany w Ustawienia > Głosy.",
    ["{name}, the Windows default input. Settings > Voices > Microphone chooses another."] = "{name}, domyślne wejście Windows. Inne wybierzesz w Ustawienia > Głosy > Mikrofon.",
    ["Revenge ambushes"] = "Zasadzki z zemsty",
    ["Speak dialogue choices"] = "Mów wybory w dialogu",
    ["Say a dialogue choice to pick it: its words, a part of them, or its number (\"two\", \"the last one\"). If nothing fits clearly, nothing is picked. No character answers.\n\nPresses the arrow keys and Enter, so the game must be in front. Needs speech recognition on this PC. Headphones work best."] = "Powiedz wybór z dialogu, aby go wybrać: jego słowa, część tych słów albo jego numer (\"dwa\", \"ostatni\"). Jeśli nic wyraźnie nie pasuje, nic nie zostaje wybrane. Żadna postać nie odpowiada.\n\nNaciska klawisze strzałek i Enter, więc gra musi być na pierwszym planie. Wymaga rozpoznawania mowy na tym komputerze. Najlepiej działają słuchawki.",
    ["No option matched. Say its number."] = "Żadna opcja nie pasuje. Powiedz jej numer.",
    ["Two options fit. Say its number."] = "Pasują dwie opcje. Powiedz jej numer.",
    ["Speaking a choice needs speech recognition on this PC."] = "Mówienie wyboru wymaga rozpoznawania mowy na tym komputerze.",
    ["AMD’s ROCm PyTorch does not support this card yet."] = "ROCm PyTorch od AMD nie obsługuje jeszcze tej karty.",
    ["Another setup is already running. Wait for it to finish."] = "Inna konfiguracja już działa. Poczekaj, aż się zakończy.",
    ["Cancelled"] = "Anulowano",
    ["Cancelling…"] = "Anulowanie…",
    ["Checking your card…"] = "Sprawdzanie twojej karty…",
    ["Downloading {done} of {total} MB ({percent}%)"] = "Pobieranie: {done} z {total} MB ({percent}%)",
    ["Downloading…"] = "Pobieranie…",
    ["Experimental. Pocket speaks until it is ready. A local voice never switches to a cloud voice."] = "Eksperymentalne. Pocket mówi, dopóki OmniVoice nie będzie gotowy. Głos lokalny nigdy nie przełącza się na głos w chmurze.",
    ["Frees about {disk} GB."] = "Zwalnia około {disk} GB.",
    ["Frees the space it took."] = "Zwalnia miejsce, które zajmował.",
    ["Install"] = "Zainstaluj",
    ["Installed"] = "Zainstalowane",
    ["Installed. OmniVoice uses it when it starts."] = "Zainstalowane. OmniVoice użyje go po uruchomieniu.",
    ["It is kept in the mod’s data folder on drive C:."] = "Jest przechowywany w folderze danych modu na dysku C:.",
    ["It runs in the background while you play. The game keeps running and nothing else changes."] = "Działa w tle, kiedy grasz. Gra działa dalej i nic innego się nie zmienia.",
    ["It takes about {disk} GB on drive C: in the mod’s data folder."] = "Zajmuje około {disk} GB na dysku C: w folderze danych modu.",
    ["MIOpen convolutions (AMD)"] = "Konwolucje MIOpen (AMD)",
    ["Not available on this PC. It needs an AMD Radeon card and the OmniVoice pack."] = "Niedostępne na tym komputerze. Potrzebna jest karta AMD Radeon i pakiet OmniVoice.",
    ["OmniVoice for AMD"] = "OmniVoice dla AMD",
    ["OmniVoice on AMD: set up first"] = "OmniVoice na AMD: najpierw skonfiguruj",
    ["OmniVoice then no longer starts on this card until it is set up again."] = "OmniVoice wtedy nie uruchomi się na tej karcie, dopóki nie zostanie skonfigurowany ponownie.",
    ["On: AMD’s MIOpen runs the convolutions, with MIOPEN_FIND_MODE=2 and MIOPEN_FIND_ENFORCE=1. Off: PyTorch’s own convolutions. Which is faster depends on your card and driver: if voices are slow or stop part-way, try the other one. AMD cards only. OmniVoice restarts with the new choice when it is idle."] = "Włączone: MIOpen od AMD wykonuje konwolucje, z MIOPEN_FIND_MODE=2 i MIOPEN_FIND_ENFORCE=1. Wyłączone: własne konwolucje PyTorch. Która jest szybsza, zależy od karty i sterownika: jeśli głosy są wolne albo urywają się w połowie, spróbuj drugiej. Tylko karty AMD. OmniVoice uruchomi się ponownie z nowym wyborem, gdy będzie bezczynny.",
    ["Own Python"] = "Własny Python",
    ["Ready"] = "Gotowe",
    ["Ready. OmniVoice runs on {card} with AMD’s ROCm."] = "Gotowe. OmniVoice działa na {card} z ROCm od AMD.",
    ["Reinstall"] = "Zainstaluj ponownie",
    ["Remove AMD setup"] = "Usuń konfigurację AMD",
    ["Removing the AMD setup…"] = "Usuwanie konfiguracji AMD…",
    ["Run OmniVoice on your AMD Radeon card with AMD’s ROCm: one download, set up from here."] = "Uruchom OmniVoice na swojej karcie AMD Radeon z ROCm od AMD: jedno pobranie, skonfigurowane stąd.",
    ["Set up OmniVoice for AMD"] = "Skonfiguruj OmniVoice dla AMD",
    ["Starting the AMD setup…"] = "Uruchamianie konfiguracji AMD…",
    ["Testing it on your card…"] = "Testowanie na twojej karcie…",
    ["The AMD setup was removed."] = "Konfiguracja AMD została usunięta.",
    ["The OmniVoice pack is not installed. Install it first."] = "Pakiet OmniVoice nie jest zainstalowany. Najpierw go zainstaluj.",
    ["The conversation service is not running. Restart the game."] = "Usługa rozmów nie działa. Uruchom grę ponownie.",
    ["The download did not finish. Check your connection and try again."] = "Pobieranie nie zostało ukończone. Sprawdź połączenie i spróbuj ponownie.",
    ["The download is not ready yet in this version of the mod."] = "Pobieranie nie jest jeszcze dostępne w tej wersji modu.",
    ["The downloaded files did not check out. Try again."] = "Pobrane pliki nie przeszły sprawdzenia. Spróbuj ponownie.",
    ["The files could not be unpacked. Try again."] = "Nie udało się rozpakować plików. Spróbuj ponownie.",
    ["The setup did not finish. Try again."] = "Konfiguracja nie została ukończona. Spróbuj ponownie.",
    ["The setup did not pass the test on your card, so OmniVoice cannot use it."] = "Konfiguracja nie przeszła testu na twojej karcie, więc OmniVoice nie może jej użyć.",
    ["The setup is installed but did not pass the test on your card. Choose Reinstall."] = "Konfiguracja jest zainstalowana, ale nie przeszła testu na twojej karcie. Wybierz Zainstaluj ponownie.",
    ["There is not enough free space on drive C:. Free some up and try again."] = "Na dysku C: jest za mało wolnego miejsca. Zwolnij trochę i spróbuj ponownie.",
    ["This PC has no AMD Radeon card this setup can use."] = "Ten komputer nie ma karty AMD Radeon, którą ta konfiguracja może użyć.",
    ["Unpacking…"] = "Rozpakowywanie…",
    ["Your own Python (omni-python.txt) is used instead. Delete that file to use this setup."] = "Zamiast tego używany jest twój własny Python (omni-python.txt). Usuń ten plik, aby użyć tej konfiguracji.",
    ["your AMD card"] = "twoja karta AMD",
    ["{voice} · AMD: set up first"] = "{voice} · AMD: najpierw skonfiguruj",
    ["The AMD setup (Settings > Voices > OmniVoice for AMD) runs OmniVoice with ROCm on {card}. Experimental."] = "Konfiguracja AMD (Ustawienia > Głosy > OmniVoice dla AMD) uruchamia OmniVoice z ROCm na {card}. Eksperymentalne.",
    ["The AMD setup was not used: {reason}. Choose Reinstall in Settings > Voices > OmniVoice for AMD. Until then Pocket speaks."] = "Konfiguracja AMD nie została użyta: {reason}. Wybierz Zainstaluj ponownie w Ustawienia > Głosy > OmniVoice dla AMD. Do tego czasu mówi Pocket.",
    ["Borrow eddies from your characters, lend them eddies and pay each other back, by talking. Each character has money of their own, as their story has it, and decides by how they feel about you. Now and then they ask you for a loan.\n\nEddies change hands as soon as a character agrees, and only with your own characters (party, invited visitors, housemates). The game’s own characters only talk about it. Off by default."] = "Pożyczaj eurodolary od postaci, pożyczaj im i oddawajcie sobie, rozmawiając. Każda ma własne pieniądze i decyduje według tego, co do ciebie czuje. Czasem prosi cię o pożyczkę.\n\nEurodolary zmieniają właściciela, gdy tylko postać się zgodzi, i tylko z twoimi postaciami (drużyna, goście, współlokatorzy). Postacie z gry tylko o tym mówią. Domyślnie wyłączone.",
    ["Eddies with characters"] = "Eurodolary z postaciami",
    ["The eddies could not be moved."] = "Nie udało się przenieść eurodolarów.",
    ["You do not have enough eddies for that."] = "Nie masz na to wystarczająco dużo eurodolarów.",
    ["{name} is no longer with you, so no eddies moved."] = "{name} nie jest już z tobą, więc nie przeniesiono żadnych eurodolarów.",
    ["Add to favorites"] = "Dodaj do ulubionych",
    ["One download of about {size} GB."] = "Jedno pobranie, około {size} GB.",
    ["One download."] = "Jedno pobranie.",
    ["Use the Search box, top right"] = "Użyj pola wyszukiwania",
    ["Search by name"] = "Szukaj po nazwie",
    ["Search"] = "Szukaj",
    ["The search box could not open."] = "Nie udało się otworzyć pola wyszukiwania.",
    ["Type part of a name"] = "Wpisz część nazwy",
    ["Opens a text box over the game. Type part of a name and press Enter: the list shows every match on every page and letter. Esc leaves the list as it is, and Enter on an empty box shows the whole list again. Case and accents do not matter, and every word you type has to match the start of a word in the name."] = "Otwiera pole tekstowe nad grą. Wpisz część nazwy i naciśnij Enter: lista pokazuje wszystkie wyniki na wszystkich stronach i literach. Esc zostawia listę bez zmian, a Enter w pustym polu znów pokazuje całą listę. Wielkość liter i akcenty nie mają znaczenia, a każde wpisane słowo musi pasować do początku jakiegoś słowa w nazwie.",
    ["How to search"] = "Jak szukać",
    ["search: {query} · {count} found"] = "wyszukiwanie: {query} · znaleziono {count}",
    ["Empties the Search box and shows the whole list again."] = "Opróżnia pole wyszukiwania i znów pokazuje całą listę.",
    ["Click the Search box at the top right of this panel (it is dim until you click it) and type a name. The list shows every match on every page and letter. Case and accents do not matter, and every word you type has to match the start of a word in the name."] = "Kliknij pole wyszukiwania w prawym górnym rogu tego panelu (jest przyciemnione, dopóki w nie nie klikniesz) i wpisz imię lub nazwę. Lista pokazuje wszystkie wyniki na wszystkich stronach i literach. Wielkość liter i akcenty nie mają znaczenia, a każde wpisane słowo musi pasować do początku jakiegoś słowa w nazwie.",
    ["Click the Search box at the top right of this panel and type a name."] = "Kliknij pole wyszukiwania w prawym górnym rogu tego panelu i wpisz imię lub nazwę.",
    ["Remove {name} from favorites"] = "Usuń {name} z ulubionych",
    ["Remove {name}"] = "Usuń {name}",
    ["Set up OmniVoice on your AMD Radeon card with one download, and choose how it runs."] = "Skonfiguruj OmniVoice na swojej karcie AMD Radeon jednym pobraniem i wybierz, jak ma działać.",
    ["That entry cannot be a favorite."] = "Tego wpisu nie można dodać do ulubionych.",
    ["You have too many favorites. Remove one first."] = "Masz za dużo ulubionych. Najpierw usuń jeden.",
    ["Your AMD Radeon card ({card}) can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself."] = "Twoja karta AMD Radeon ({card}) może uruchomić OmniVoice. Skonfiguruj go w Ustawienia > Głosy > OmniVoice dla AMD: jedno pobranie, potem uruchomi się samo.",
    ["Your favorites could not be saved, so they last only until the game closes."] = "Ulubionych nie udało się zapisać, więc przetrwają tylko do zamknięcia gry.",
    ["{count} matching characters"] = "Pasujących postaci: {count}",
    ["{name} is no longer a favorite."] = "{name} nie jest już w ulubionych.",
    ["A saved party holds {count} characters, so the rest were left out."] = "Zapisana drużyna mieści {count} postaci, więc reszta została pominięta.",
    ["Already with you: {names}."] = "Już są z tobą: {names}.",
    ["Another saved party already has that name."] = "Inna zapisana drużyna ma już taką nazwę.",
    ["Could not invite: {names}."] = "Nie udało się zaprosić: {names}.",
    ["Deletes this saved party. The characters in your party now are not touched."] = "Usuwa tę zapisaną drużynę. Postaci, które są teraz w twojej drużynie, nie zostaną ruszone.",
    ["Invites the characters of this party to your side: {names}.\n\nIt adds to your party and dismisses nobody. A character who is already with you is not invited twice. Anyone who cannot come is named, with the reason."] = "Zaprasza postaci z tej drużyny do ciebie: {names}.\n\nDodaje je do twojej drużyny i nikogo nie odsyła. Postać, która już jest z tobą, nie zostanie zaproszona ponownie. Każdy, kto nie może przyjść, zostanie wymieniony wraz z powodem.",
    ["Parties"] = "Drużyny",
    ["Party"] = "Drużyna",
    ["Press Delete again to delete {name}."] = "Naciśnij Usuń ponownie, aby usunąć {name}.",
    ["Press again"] = "Naciśnij ponownie",
    ["Press again to delete this saved party. Anything else cancels."] = "Naciśnij ponownie, aby usunąć tę zapisaną drużynę. Cokolwiek innego anuluje.",
    ["Rename"] = "Zmień nazwę",
    ["Rename party"] = "Zmień nazwę drużyny",
    ["Renamed to {name}."] = "Zmieniono nazwę na {name}.",
    ["Replaces the characters of this saved party with the ones in your party now."] = "Zastępuje postacie tej zapisanej drużyny tymi, które są teraz w twojej drużynie.",
    ["Save current party"] = "Zapisz obecną drużynę",
    ["Saved as {name}. Press Spawn party under it to invite them again."] = "Zapisano jako {name}. Naciśnij pod nią Zaproś drużynę, aby zaprosić ich ponownie.",
    ["Saved party: {name}"] = "Zapisana drużyna: {name}",
    ["Saves the characters in your party now, copies and your own characters included, as a party you can invite again with one press. It is named Party 1, Party 2 and so on, and appears below.\n\nYou keep up to {count} saved parties."] = "Zapisuje postacie, które są teraz w twojej drużynie, włącznie z kopiami i twoimi własnymi postaciami, jako drużynę, którą możesz zaprosić ponownie jednym naciśnięciem. Nazywa się Drużyna 1, Drużyna 2 i tak dalej, i pojawia się poniżej.\n\nMożesz zachować do {count} zapisanych drużyn.",
    ["Spawn"] = "Zaproś",
    ["Spawn party"] = "Zaproś drużynę",
    ["That party no longer exists."] = "Ta drużyna już nie istnieje.",
    ["The characters of this party: {names}."] = "Postacie tej drużyny: {names}.",
    ["The party could not be saved."] = "Nie udało się zapisać drużyny.",
    ["This menu has no text box, so the party keeps its name. Mod Configuration Menu has one: type the name in its Search box."] = "To menu nie ma pola tekstowego, więc drużyna zachowuje nazwę. Mod Configuration Menu ma takie pole: wpisz nazwę w jego polu wyszukiwania.",
    ["Type the new name in the Search box at the top (Mod Configuration Menu), then press Rename. Native Settings UI has no text box, so a party keeps its name there."] = "Wpisz nową nazwę w pole wyszukiwania na górze (Mod Configuration Menu), a potem naciśnij Zmień nazwę. Native Settings UI nie ma pola tekstowego, więc tam drużyna zachowuje nazwę.",
    ["Type the new name in the Search box first, then press Rename."] = "Najpierw wpisz nową nazwę w pole wyszukiwania, a potem naciśnij Zmień nazwę.",
    ["Update"] = "Zaktualizuj",
    ["Update with current party"] = "Zaktualizuj obecną drużyną",
    ["You can keep {count} saved parties. Delete one first."] = "Możesz zachować {count} zapisanych drużyn. Najpierw usuń jedną.",
    ["Your party is empty. Invite someone first."] = "Twoja drużyna jest pusta. Najpierw kogoś zaproś.",
    ["Your saved parties could not be written to disk, so they last only until the game closes."] = "Zapisanych drużyn nie udało się zapisać na dysku, więc przetrwają tylko do zamknięcia gry.",
    ["that character model is unavailable"] = "model tej postaci jest niedostępny",
    ["the invitation was refused"] = "zaproszenie zostało odrzucone",
    ["{name} ({count})"] = "{name} ({count})",
    ["{name} ({reason})"] = "{name} ({reason})",
    ["{name} deleted."] = "Usunięto: {name}.",
    ["{name} has nobody to invite."] = "{name} nie ma kogo zaprosić.",
    ["{name} now has the characters of your party."] = "{name} ma teraz postacie z twojej drużyny.",
    ["{party}: inviting {names}."] = "{party}: zaprasza {names}.",
    ["Adds {name} to your favorites. They are listed at the top of page 1, and first in the phone’s Chat tab. Updates never touch them."] = "Dodaje {name} do ulubionych. Są wymienione na początku strony 1 oraz jako pierwsze w zakładce Czat w telefonie. Aktualizacje nigdy ich nie ruszają.",
    ["Favorites"] = "Ulubione",
    ["Only the first {count} favorites are listed here. The others are in the list below."] = "Tutaj wyświetlono tylko pierwsze {count} ulubione. Pozostałe są na liście poniżej.",
    ["Page {page} of {pages}: {kind} {first} to {last}."] = "Strona {page} z {pages}: {kind} {first} do {last}.",
    ["Press to go to page {page} of {pages}: {kind} {first} to {last}."] = "Naciśnij, aby przejść do strony {page} z {pages}: {kind} {first} do {last}.",
    ["Takes {name} out of your favorites. Her place in the list below stays."] = "Usuwa {name} z ulubionych. Miejsce na liście poniżej pozostaje.",
    ["This is the first page."] = "To jest pierwsza strona.",
    ["This is the last page."] = "To jest ostatnia strona.",
    ["characters"] = "postacie",
    ["entries"] = "wpisy",
    ["models"] = "modele",
    ["{count} more favorites"] = "{count} więcej ulubionych",
    ["{name} is now a favorite. Favorites are at the top of page 1."] = "{name} jest teraz w ulubionych. Ulubione są na początku strony 1.",
    ["Favorite"] = "Ulubiony",
    ["That look is not one of this character’s."] = "Ten wygląd nie należy do tej postaci.",
    ["That choice is not available."] = "Ten wybór jest niedostępny.",
    ["The editor keeps choices for {max} characters. Reset one first."] = "Edytor przechowuje wybory dla {max} postaci. Najpierw zresetuj jedną.",
    ["Usual look"] = "Zwykły wygląd",
    ["Home clothes: tank top, boxer shorts, flip-flops"] = "Ubrania domowe: podkoszulka, bokserki, klapki",
    ["No jacket"] = "Bez kurtki",
    ["No jacket and harness"] = "Bez kurtki, z uprzężą",
    ["Home clothes: shirt and trousers"] = "Ubrania domowe: koszula i spodnie",
    ["Home clothes: tank top and trousers"] = "Ubrania domowe: podkoszulka i spodnie",
    ["Hooded jacket"] = "Kurtka z kapturem",
    ["Home clothes: t-shirt and trousers"] = "Ubrania domowe: koszulka i spodnie",
    ["Collar down"] = "Kołnierz opuszczony",
    ["Valentino look"] = "Wygląd Valentino",
    ["Suit"] = "Garnitur",
    ["Club night, no jacket"] = "Noc w klubie, bez kurtki",
    ["Solo look"] = "Wygląd Solo",
    ["Date night"] = "Wieczór randkowy",
    ["T-shirt"] = "Koszulka",
    ["Vest"] = "Kamizelka",
    ["Paradise look"] = "Wygląd Paradise",
    ["Bartender"] = "Barman",
    ["Dress without the fur coat"] = "Sukienka bez futrzanego płaszcza",
    ["Trench coat"] = "Trencz",
    ["Without the coat"] = "Bez płaszcza",
    ["CEO look with coat"] = "Wygląd CEO z płaszczem",
    ["CEO look"] = "Wygląd CEO",
    ["Pyjamas"] = "Piżama",
    ["Valentino look, collar open"] = "Wygląd Valentino, rozpięty kołnierz",
    ["Vest and rucksack"] = "Kamizelka i plecak",
    ["Arasaka work clothes, no jacket"] = "Ubranie robocze Arasaki, bez marynarki",
    ["Red parade dress"] = "Czerwona suknia paradna",
    ["Red parade dress with bracelets"] = "Czerwona suknia paradna z bransoletami",
    ["Party dress"] = "Sukienka imprezowa",
    ["Tank top"] = "Podkoszulka",
    ["Street clothes"] = "Ubranie uliczne",
    ["Merc look"] = "Wygląd najemnika",
    ["Go back to the usual look and moves for {name}? Your choices on this part are removed."] = "Wrócić do zwykłego wyglądu i ruchów dla {name}? Twoje wybory w tej części zostaną usunięte.",
    ["Back to the usual look and moves."] = "Przywrócono zwykły wygląd i ruchy.",
    ["Choices for how this character looks and moves. They work with every conversation option, Convai included, except the reply length."] = "Wybory dotyczące wyglądu i ruchów tej postaci. Działają ze wszystkimi opcjami rozmowy, także z Convai, z wyjątkiem długości odpowiedzi.",
    ["Outfit"] = "Strój",
    ["Automatic follows the “Companions change outfits” setting in the game: day and night looks, now and then a change, and casual clothes at home. A look you pick is worn all the time. Only your own companions and residents are dressed, and they change while nobody is looking. Characters the game places are never changed."] = "Tryb Auto działa zgodnie z ustawieniem gry „Towarzysze zmieniają stroje”: wygląd dzienny i nocny, od czasu do czasu zmiana oraz codzienne ubrania w domu. Wybrany wygląd jest noszony cały czas. Ubierani są tylko Twoi towarzysze i mieszkańcy, a zmiany następują, gdy nikt nie patrzy. Postaci umieszczone przez grę nigdy nie są zmieniane.",
    ["This character has only one look in the game files, so there is no outfit to choose."] = "Ta postać ma w plikach gry tylko jeden wygląd, więc nie ma stroju do wyboru.",
    ["Talking gestures"] = "Gesty podczas mówienia",
    ["How the hands move while they speak a longer reply."] = "Jak poruszają się ręce, gdy mówi dłuższą odpowiedź.",
    ["Normal"] = "Normalnie",
    ["Calm: smaller gestures, not as often"] = "Spokojnie: mniejsze gesty, rzadziej",
    ["Lively: bigger gestures, more often"] = "Żywiołowo: większe gesty, częściej",
    ["None: the hands stay at rest"] = "Brak: ręce pozostają w spoczynku",
    ["Nod while you talk to them"] = "Kiwanie głową podczas rozmowy",
    ["A small nod now and then while you speak."] = "Od czasu do czasu lekkie skinięcie głową, gdy mówisz.",
    ["Idle moves"] = "Ruchy podczas postoju",
    ["What they do now and then while they stand beside you."] = "Co robi od czasu do czasu, gdy stoi obok Ciebie.",
    ["Plain stances only, no props like a cup or a cigarette"] = "Tylko proste postawy, bez rekwizytów, np. kubka czy papierosa",
    ["None: they keep the stance they have"] = "Brak: zachowuje swoją postawę",
    ["Sit down and take a place"] = "Usiąść i zająć miejsce",
    ["Takes a seat beside you when you sit, and a seat or a spot in your flat at home. Switched off, they stay on their feet beside you."] = "Gdy siadasz, zajmuje miejsce obok Ciebie; w Twoim mieszkaniu zajmuje siedzenie lub wyznaczone miejsce. Po wyłączeniu zostaje na nogach obok Ciebie.",
    ["Comment on fights and loot"] = "Komentowanie walk i łupów",
    ["Switched off, they say nothing about fights or about what you pick up."] = "Po wyłączeniu nic nie mówi o walkach ani o przedmiotach, które podnosisz.",
    ["Reply length"] = "Długość odpowiedzi",
    ["Shorter: up to about {words} words"] = "Krótsza: do około {words} słów",
    ["Very short: up to about {words} words"] = "Bardzo krótka: do około {words} słów",
    ["A saved choice counts within a few seconds. Clothes change when nobody is looking."] = "Zapisany wybór działa w ciągu kilku sekund. Ubrania zmieniają się, gdy nikt nie patrzy.",
    ["Look and moves"] = "Wygląd i ruchy",
    ["Shift"] = "Shift",
    ["Ctrl"] = "Ctrl",
    ["Alt"] = "Alt",
    ["Hold Shift, Ctrl or Alt while you press a key to set a combination such as Shift+F5. A combination runs only with exactly those keys held, and a plain key does not run while one is held. In the game Shift sprints, Ctrl dodges and Alt opens the weapon wheel, so V does that too."] = "Przytrzymaj Shift, Ctrl lub Alt podczas naciskania klawisza, aby ustawić kombinację, na przykład Shift+F5. Kombinacja działa tylko przy dokładnie tych przytrzymanych klawiszach, a zwykły klawisz nie działa, gdy któryś z nich jest przytrzymany. W grze Shift oznacza sprint, Ctrl unik, a Alt otwiera koło broni, więc V też to zrobi.",
    ["Disk space"] = "Miejsce na dysku",
    ["Your {drive} drive is almost full ({free} GB free). Free space so the mod can save logs and memories."] = "Twój dysk {drive} jest prawie pełny ({free} GB wolnego). Zrób miejsce na logi i wspomnienia moda.",
    ["An input marked (!) looks like a loopback or virtual input, such as Stereo Mix, CABLE Output or a mixer’s Out. It can carry other apps’ sound, for example the far side of a call, so the mod never picks one by itself."] = "Wejście oznaczone (!) wygląda na pętlę zwrotną lub wirtualne wejście, na przykład Stereo Mix, CABLE Output albo wyjście miksera. Może przenosić dźwięk innych aplikacji, na przykład drugiej strony rozmowy, dlatego mod sam nigdy takiego nie wybiera.",
    ["The input you chose looks like it carries PC sound, not only your voice. If characters hear your calls, choose your real microphone."] = "Wybrane wejście wygląda na takie, które przenosi dźwięk komputera, a nie tylko twój głos. Jeśli postacie słyszą twoje rozmowy, wybierz prawdziwy mikrofon.",
    ["{name} looks like it carries PC sound, such as a call, not only your voice. Choose your real microphone in Settings > Voices > Microphone."] = "{name} wygląda na takie, które przenosi dźwięk komputera, na przykład rozmowę, a nie tylko twój głos. Wybierz prawdziwy mikrofon w Ustawienia > Głosy > Mikrofon.",
    ["No API key is saved yet. Copy your key from your provider, press Paste API key, then test again."] = "Klucz API nie został jeszcze zapisany. Skopiuj swój klucz od dostawcy, naciśnij Wklej klucz API, a potem przetestuj ponownie.",
    ["Add"] = "Dodaj",
    ["Deletes this free setup: the endpoint URL, the model ID and the API key saved with it."] = "Usuwa tę darmową konfigurację: adres URL endpointu, identyfikator modelu i zapisany z nią klucz.",
    ["Allow Local AI to use RAM"] = "Zezwól Local AI na używanie RAM",
    ["Off: when the Local AI model you chose does not fit the free graphics memory beside the game, a smaller model that fits is loaded instead, with one notice.\n\nOn: your chosen model is kept and part of it runs from system memory (RAM) on the processor. Replies are slower, and you are told once. It needs enough free RAM, and the game may have less processor time."] = "Wyłączone: gdy wybrany model Local AI nie mieści się w wolnej pamięci graficznej obok gry, ładowany jest mniejszy, z jednym powiadomieniem.\n\nWłączone: wybrany model zostaje, a jego część działa z pamięci systemowej (RAM) na procesorze. Odpowiedzi są wolniejsze i dostajesz jedno powiadomienie. Potrzeba dość wolnej pamięci RAM, a gra może mieć mniej czasu procesora.",
    ["Using {model}"] = "Używa {model}",
    ["{model} is in use because the model you chose did not fit beside the game. Your choice is unchanged."] = "Używany jest {model}, ponieważ wybrany model nie mieścił się obok gry. Twój wybór pozostaje bez zmian.",
    ["Local AI is keeping {model} as you allowed, with part of it in system memory. Replies will be slower."] = "Local AI zachowuje {model} zgodnie z twoim wyborem, część działa w pamięci systemowej. Odpowiedzi będą wolniejsze.",
    ["Choosing Convai or Google Gemini turns it off. Voxtral is not used with it: a voice on Voxtral moves to Pocket and comes back when it is turned off."] = "Wybór Convai lub Google Gemini wyłącza tę opcję. Voxtral nie jest z nią używany: głos Voxtral przechodzi na Pocket i wraca po wyłączeniu.",
    ["Convai could not sign in. Try again in a moment, or choose Google Gemini or Local AI in Settings > Conversation provider."] = "Nie udało się zalogować do Convai. Spróbuj ponownie za chwilę albo wybierz Google Gemini lub Local AI w Ustawieniach > Dostawca rozmów.",
    ["Convai is answering right now. Your changes reach it as notes sent with each reply, so it may follow them a little less exactly than Google Gemini, Local AI or Custom."] = "Convai właśnie odpowiada. Twoje zmiany docierają do niego jako notatki wysyłane przy każdej odpowiedzi, więc może je wykonywać nieco mniej dokładnie niż w przypadku Google Gemini, Local AI albo Własnego.",
    ["A long edit is shortened for Convai. The rules, memories and speaking style are kept first."] = "Długa zmiana jest skracana dla Convai. Najpierw zachowywane są zasady, wspomnienia i sposób mówienia.",
    ["Convai: Google Gemini has no key yet"] = "Convai: Google Gemini nie ma jeszcze klucza",
    ["Copy your Mistral API key first, then press Add. It fills in the endpoint URL and the model ID for Mistral (Ministral 8B) and saves your key from the clipboard. The same key powers the Voxtral cloud voice.\n\nNew Mistral accounts may not get a free API key any more."] = "Najpierw skopiuj swój klucz API z Mistral, a potem naciśnij Add. Uzupełni adres URL endpointu i identyfikator modelu dla Mistral (Ministral 8B) i zapisze twój klucz ze schowka. Ten sam klucz obsługuje chmurowy głos Voxtral.\n\nNowe konta Mistral mogą już nie dostawać darmowego klucza API.",
    ["Copy your key from Google AI Studio first (aistudio.google.com/apikey, a Google account is enough, no card). It is read from the clipboard once and saved on this computer.\n\nThe free plan has a daily limit of about 500 replies, is not offered in every country, and Google may use free-plan chats to improve its products."] = "Najpierw skopiuj swój klucz z Google AI Studio (aistudio.google.com/apikey, wystarczy konto Google, bez karty). Jest odczytany ze schowka jeden raz i zapisany na tym komputerze.\n\nDarmowy plan ma dzienny limit około 500 odpowiedzi, nie jest dostępny w każdym kraju, a Google może wykorzystywać rozmowy z darmowego planu do ulepszania swoich produktów.",
    ["Edit a character’s bio, speaking style, speaking rules and memories, and the prompting for each AI option, or make a character of your own, in your browser.\n\nWorks with every conversation option. With Convai, your changes are sent as notes with each reply. Changes apply from the next reply."] = "Edytuj w przeglądarce biogram, sposób mówienia, zasady mówienia i wspomnienia postaci oraz prompt dla każdej opcji AI albo stwórz własną postać.\n\nDziała z każdą opcją rozmowy. Z Convai twoje zmiany są wysyłane jako notatki przy każdej odpowiedzi. Zmiany obowiązują od następnej odpowiedzi.",
    ["Edit characters’ bios, rules and memories, and the prompting for each AI option, in your browser.\n\nWorks with every conversation option. With Convai, your changes are sent as notes with each reply. Changes apply from the next reply."] = "Edytuj w przeglądarce biogramy, zasady i wspomnienia postaci oraz prompt dla każdej opcji AI.\n\nDziała z każdą opcją rozmowy. Z Convai twoje zmiany są wysyłane jako notatki przy każdej odpowiedzi. Zmiany obowiązują od następnej odpowiedzi.",
    ["From Convai or Google Gemini, turning it on selects Local AI, or Custom when Local AI is not installed. With Local AI it also selects the largest uncensored model that fits. Turning it off restores your choices."] = "Po włączeniu w Convai lub Google Gemini wybierane jest Local AI, a gdy Local AI nie jest zainstalowane, Własny. Przy Local AI wybierany jest też największy model bez cenzury, który się zmieści. Wyłączenie przywraca twoje wybory.",
    ["Google Gemini (free plan)"] = "Google Gemini (darmowy plan)",
    ["Google Gemini API key"] = "Klucz API Google Gemini",
    ["Google Gemini has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Google Gemini nie ma jeszcze klucza, więc używane jest Convai. Dodaj swój klucz w Ustawieniach > Dostawca rozmów.",
    ["Google Gemini replies are spoken by a local voice instead of the Convai cloud voice."] = "Odpowiedzi Google Gemini wypowiada lokalny głos, a nie chmurowy głos Convai.",
    ["Google Gemini: key not accepted"] = "Google Gemini: klucz nie został zaakceptowany",
    ["The service is not available in your region."] = "Usługa nie jest dostępna w Twoim regionie.",
    ["Google accepted the key."] = "Google zaakceptował klucz.",
    ["Google did not accept this key. Check it in Google AI Studio, then Remove it and Add the right one."] = "Google nie zaakceptował tego klucza. Sprawdź go w Google AI Studio, potem kliknij Usuń i dodaj właściwy przyciskiem Dodaj.",
    ["Google accepted the key, but the free allowance is used up for now."] = "Google zaakceptował klucz, ale darmowy limit na razie się wyczerpał.",
    ["The key is saved, but Google Gemini is not available in your region."] = "Klucz został zapisany, ale Google Gemini nie jest dostępny w Twoim regionie.",
    ["The key is saved, but Google could not be reached to check it."] = "Klucz został zapisany, ale nie udało się połączyć z Google, żeby go sprawdzić.",
    ["Google Gemini: rate limited for a minute"] = "Google Gemini: limit na minutę",
    ["Google Gemini: free allowance used up for today"] = "Google Gemini: darmowy limit na dziś wyczerpany",
    ["Google Gemini: not available in your region"] = "Google Gemini: niedostępny w Twoim regionie",
    ["Google did not accept your Gemini key. Check it in Google AI Studio and add it again."] = "Google nie przyjął Twojego klucza Gemini. Sprawdź go w Google AI Studio i dodaj ponownie.",
    ["Your free Gemini allowance for today is used up. It resets at {time}. Use Convai or Local AI."] = "Twój darmowy limit Gemini na dziś się wyczerpał. Odnowi się o {time}. Użyj Convai lub Local AI.",
    ["Your free Gemini allowance for today is used up. It resets tomorrow. Use Convai or Local AI."] = "Twój darmowy limit Gemini na dziś się wyczerpał. Odnowi się jutro. Użyj Convai lub Local AI.",
    ["Google Gemini is rate limiting you. Wait a minute, then try again."] = "Google Gemini ogranicza zapytania. Poczekaj minutę i spróbuj ponownie.",
    ["Google Gemini is not available in your region. Use Convai or Local AI."] = "Google Gemini nie jest dostępny w Twoim regionie. Użyj Convai lub Local AI.",
    ["Google Gemini is busy or had an error. Wait a minute, then try again."] = "Google Gemini jest zajęty lub wystąpił błąd. Poczekaj minutę i spróbuj ponownie.",
    ["Google Gemini could not be reached. Check your internet connection, then try again."] = "Brak połączenia z Google Gemini. Sprawdź internet i spróbuj ponownie.",
    ["The Gemini model is not available right now. Try again later or use Local AI."] = "Model Gemini jest teraz niedostępny. Spróbuj później lub użyj Local AI.",
    ["Google Gemini: model unavailable"] = "Google Gemini: model niedostępny",
    ["Mistral (your key)"] = "Mistral (twój klucz)",
    ["Requires a Mistral key (add it with the Mistral preset on the Custom endpoint page)"] = "Wymaga klucza Mistral (dodaj go przez preset Mistral na stronie Custom endpoint)",
    ["The conversation limit has been reached. Try again later, or choose Local AI or Google Gemini in Settings > Conversation provider."] = "Osiągnięto limit rozmów. Spróbuj ponownie później albo wybierz Local AI lub Google Gemini w Ustawieniach > Dostawca rozmów.",
    ["The longest reply, in words. Works with Google Gemini, Local AI and Custom, not Convai."] = "Najdłuższa odpowiedź, w słowach. Działa z Google Gemini, Local AI i Custom, nie z Convai.",
    ["They join as a copy of the model they were made from. They talk with Google Gemini, Local AI or Custom; with Convai they talk as an ordinary person."] = "Dołącza jako kopia modelu, na podstawie którego powstała. Rozmawia przez Google Gemini, Local AI albo Własny; z Convai mówi jak zwykła osoba.",
    ["Today’s Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "Dziś tury Convai zużyte.\nOdnowi się o {time}. Spróbuj Local AI (bez limitu) lub Google Gemini (własny klucz)",
    ["Today’s Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "Dziś tury Convai zużyte.\nSpróbuj Local AI (bez limitu) lub Google Gemini (własny klucz)",
    ["Today’s {limit} Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "Dziś {limit} tur Convai zużyte.\nOdnowi się o {time}. Spróbuj Local AI (bez limitu) lub Google Gemini (własny klucz)",
    ["Today’s {limit} Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "Dziś {limit} tur Convai zużyte.\nSpróbuj Local AI (bez limitu) lub Google Gemini (własny klucz)",
    ["Turns the content pack {name} on or off. A pack changes how the characters talk. Its prompt changes work with Google Gemini, Local AI and Custom. On Convai its world rules and its own Convai characters apply. A switch counts from the next reply, new names after a restart."] = "Włącza lub wyłącza pakiet treści {name}. Pakiet zmienia sposób mówienia postaci. Jego zmiany promptu działają z Google Gemini, Local AI i Własnym. W Convai obowiązują jego zasady świata i własne postacie Convai. Przełączenie działa od następnej odpowiedzi, nowe imiona po restarcie.",
    ["What the game tells each character about this moment. A character mentions it only when it fits the talk.\n\nAn off kind is left out of every conversation provider (Convai, Google Gemini, Local AI and Custom)."] = "Co gra mówi każdej postaci o tej chwili. Postać wspomina o tym tylko wtedy, gdy pasuje to do rozmowy.\n\nWyłączona informacja nie trafia do żadnego dostawcy rozmów (Convai, Google Gemini, Local AI i Własny).",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Kto pisze odpowiedzi twoich towarzyszy. Zmiana czeka, aż żadna rozmowa nie będzie trwać.\n\nDarmowy plan Convai nie wymaga konfiguracji i daje lepsze odpowiedzi. Klucz API Convai używa twojego własnego klucza. Google Gemini używa twojego własnego darmowego klucza, a pamięć pozostaje na tym komputerze.\n\nPrzy Google Gemini, Local AI lub Własnym głos w chmurze Convai zostaje zastąpiony lokalnym głosem. Mowa jest rozpoznawana na tym komputerze, więc klawisz głosowy działa.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Kto pisze odpowiedzi twoich towarzyszy. Zmiana czeka, aż żadna rozmowa nie będzie trwać.\n\nDarmowy plan Convai nie wymaga konfiguracji i daje lepsze odpowiedzi. Klucz API Convai używa twojego własnego klucza. Google Gemini używa twojego własnego darmowego klucza, a pamięć pozostaje na tym komputerze.\n\nPrzy Google Gemini, Local AI lub Własnym głos w chmurze Convai zostaje zastąpiony lokalnym głosem. Rozpoznawanie mowy dla klawisza głosowego nie jest jeszcze dostępne przy nich, więc wpisuj wiadomości.",
    ["You have used today’s {limit} turns, which come back at {time}. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "Wykorzystano dzisiejszy limit {limit} tur. Limit odnowi się o {time}. Aby kontynuować od razu, wybierz Local AI (bez limitu) albo Google Gemini (z własnym kluczem).",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "Wykorzystano dzisiejszy limit {limit} tur. Limit odnowi się jutro. Aby kontynuować od razu, wybierz Local AI (bez limitu) albo Google Gemini (z własnym kluczem).",
    ["Your changes work with every conversation option. With Convai they are sent as notes with each reply."] = "Twoje zmiany działają z każdą opcją rozmowy. Z Convai są wysyłane jako notatki przy każdej odpowiedzi.",
    ["Your own characters talk only with Google Gemini, Local AI or Custom. With Convai they speak as an ordinary person."] = "Twoje własne postacie rozmawiają tylko z Google Gemini, Local AI albo Własnym. Z Convai mówią jak zwykła osoba.",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom, so with Convai they talk as an ordinary person."] = "{name} jest jedną z twoich własnych postaci. Potrzebuje Google Gemini, Local AI albo Własnego, więc z Convai mówi jak zwykła osoba.",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom: choose one under Conversation provider in the settings."] = "{name} to jeden z twoich własnych postaci. Potrzebuje dostawcy: Google Gemini, Local AI albo Custom. Wybierz jednego w ustawieniach, w polu „Dostawca rozmów”.",
    ["This character needs Google Gemini, Local AI or Custom to answer."] = "Ta postać potrzebuje Google Gemini, Local AI albo Własnego, żeby odpowiadać.",
    ["You’ve reached today’s Convai free tier limit. It resets at {time}. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "Osiągnięto dzisiejszy limit darmowego planu Convai. Zresetuje się o {time}. Aby kontynuować już teraz, wybierz innego dostawcę w Ustawieniach > Dostawca rozmów. Local AI jest bez limitu i działa na tym komputerze. Google Gemini działa z twoim własnym kluczem.",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "Osiągnięto dzisiejszy limit darmowego planu Convai. Zresetuje się jutro. Aby kontynuować już teraz, wybierz innego dostawcę w Ustawieniach > Dostawca rozmów. Local AI jest bez limitu i działa na tym komputerze. Google Gemini działa z twoim własnym kluczem.",
    ["Character bonds"] = "Więzi z postaciami",
    ["Every named character has a bond with you, level 1 to 10. Quests finished together, a romance, eddies paid back and talking raise it; threats and insults lower it. Closer characters trust you more.\n\nA notice shows each level change. Forget clears the talk part. Off by default."] = "Każda nazwana postać ma z tobą więź od poziomu 1 do 10. Rośnie dzięki wspólnie wykonanym zadaniom, romansowi, oddanym eurodolarom i rozmowom, a groźby i obelgi ją obniżają. Bliższe postacie bardziej ci ufają.\n\nPowiadomienie pojawia się przy każdej zmianie poziomu. Zapomnij czyści część rozmów. Domyślnie wyłączone.",
    ["Bond with {name}: level {level}, {title}"] = "Więź z {name}: poziom {level}, {title}",
    ["Bond with {name} fell: level {level}, {title}"] = "Więź z {name} spadła: poziom {level}, {title}",
    ["Acquaintance"] = "Znajomy",
    ["Familiar face"] = "Znajoma twarz",
    ["Friendly"] = "Przyjazny",
    ["Friend"] = "Przyjaciel",
    ["Good friend"] = "Dobry przyjaciel",
    ["Close friend"] = "Bliski przyjaciel",
    ["Trusted"] = "Zaufany",
    ["Confidant"] = "Powiernik",
    ["Family"] = "Rodzina",
    ["Ride or die"] = "Wierny do końca",
    ["Story packs"] = "Pakiety historii",
    ["When you are close and a character’s own quests are done, they can start a short story of their own. It plays out in talks, texts and calls, and some use Eddies with characters and Immersive invitations.\n\nNeeds Character bonds. Own characters and channels only, never the game’s own scenes or quests. Off by default."] = "Gdy jesteś blisko postaci, a jej własne zadania są ukończone, może zacząć krótką własną historię. Rozgrywa się w rozmowach, wiadomościach i połączeniach, a niektóre używają Eurodolarów z postaciami i Immersyjnych zaproszeń.\n\nWymaga Więzi z postaciami. Tylko twoje postacie i kanały, nigdy sceny ani zadania gry. Domyślnie wyłączone.",
    ["Characters text first"] = "Postacie piszą pierwsze",
    ["Bond: level {level}, {title}"] = "Więź: poziom {level}, {title}",
    ["Story: {title}"] = "Historia: {title}",
    ["Bonds are not kept while Character bonds is off, so nobody is listed here. Turn it on in Settings, under Companions."] = "Więzi nie są zapisywane, dopóki Więzi z postaciami są wyłączone, więc nikt się tu nie pojawia. Włącz je w Ustawieniach, w sekcji Towarzysze.",
    ["Character bonds are off"] = "Więzi z postaciami są wyłączone",
    ["From their story: {story}, from talking: {talk}"] = "Z ich historii: {story}, z rozmów: {talk}",
    ["Highest level"] = "Najwyższy poziom",
    ["Hurt: {points}"] = "Urażenie: {points}",
    ["Hurt: {points}, gone in about a game day"] = "Urażenie: {points}, minie za około jeden dzień w grze",
    ["Hurt: {points}, gone in about {days} game days"] = "Urażenie: {points}, minie za około {days} dni w grze",
    ["Last talked: today"] = "Ostatnia rozmowa: dzisiaj",
    ["Last talked: yesterday"] = "Ostatnia rozmowa: wczoraj",
    ["Last talked: {days} days ago"] = "Ostatnia rozmowa: {days} dni temu",
    ["Level {level}"] = "Poziom {level}",
    ["No story yet"] = "Jeszcze bez historii",
    ["Nobody yet"] = "Jeszcze nikogo",
    ["See the characters you have talked to and how close each one is to you: the bond level, what raised or hurt it, their quests and the stories they are in."] = "Zobacz postacie, z którymi rozmawiasz, i jak blisko jest każda z nich: poziom więzi, co ją podniosło lub nadwerężyło, ich zadania i historie, w których biorą udział.",
    ["Talk to a character and your bond with them shows here."] = "Porozmawiaj z postacią, a twoja więź z nią pojawi się tutaj.",
    ["The characters you have talked to and how close each one is to you. The most recent come first."] = "Postacie, z którymi rozmawiasz, i jak blisko jest każda z nich. Najnowsze są na początku.",
    ["Their quests: {done} of {total} finished"] = "Ich zadania: ukończono {done} z {total}",
    ["Warmth: {points}"] = "Ciepło: {points}",
    ["{points} of {needed} points to level {to}"] = "{points} z {needed} punktów do poziomu {to}",
    ["{title} (finished)"] = "{title} (zakończona)",
    ["{title}: {label}"] = "{title}: {label}",
    ["Characters you are close to can text or call you first now and then, and Johnny can speak up in your head. It only happens at calm moments, never in a fight, a scene or a call, and only a few times a day.\n\nNeeds Story packs. Own characters and channels only. Off by default."] = "Postacie, z którymi jesteś blisko, mogą czasem pierwsze napisać lub zadzwonić, a Johnny może odezwać się w twojej głowie. Dzieje się to tylko w spokojnych chwilach, nigdy podczas walki, sceny ani rozmowy, i tylko kilka razy dziennie.\n\nWymaga Pakietów historii. Tylko twoje postacie i kanały. Domyślnie wyłączone.",
    ["Puts every setting on Settings, Romantic relationships, Dynamic info and Key bindings back to its default. Press the button twice to confirm."] = "Przywraca każde ustawienie w Ustawieniach, Relacjach romantycznych, Informacjach na żywo i Przypisaniach klawiszy do wartości domyślnej. Naciśnij przycisk dwa razy, aby potwierdzić.",
    ["Romantic relationships"] = "Relacje romantyczne",
    ["Add a key first"] = "Najpierw dodaj klucz",
    ["Add a key to choose it"] = "Dodaj klucz, aby ją wybrać",
    ["Asks Inworld whether your saved key is accepted. It costs nothing and no speech is made."] = "Pyta Inworld, czy zapisany klucz jest akceptowany. Nic to nie kosztuje i nie generuje się żadna mowa.",
    ["Chosen as the Companion voice"] = "Wybrano jako głos towarzysza",
    ["Connected"] = "Połączono",
    ["Deletes the saved key. If Inworld is your Companion voice, replies show as text until you add a key again."] = "Usuwa zapisany klucz. Jeśli Inworld jest twoim głosem towarzyszy, odpowiedzi są pokazywane jako tekst, dopóki nie dodasz klucza ponownie.",
    ["Inworld API key"] = "Klucz API Inworld",
    ["Inworld cloud voice"] = "Głos w chmurze Inworld",
    ["Inworld did not accept that key."] = "Inworld nie zaakceptował tego klucza.",
    ["Inworld is not used with Mature content."] = "Inworld nie jest używany z treściami dla dorosłych.",
    ["Inworld voice"] = "Głos Inworld",
    ["Inworld · Cloud voice"] = "Inworld · Głos w chmurze",
    ["Inworld · needs key"] = "Inworld · wymaga klucza",
    ["Inworld · not with Mature"] = "Inworld · bez treści 18+",
    ["Key refused"] = "Klucz odrzucony",
    ["Needs your own Inworld key, from inworld.ai. Inworld’s free plan is a one-time trial of about 70 minutes of speech, then you pay as you go.\n\nCopy your key first, then press Add. It is read from the clipboard once, checked with Inworld and saved on this computer."] = "Potrzebujesz własnego klucza Inworld, z inworld.ai. Darmowy plan Inworld to jednorazowy test około 70 minut mowy, potem płacisz za wykorzystanie.\n\nNajpierw skopiuj klucz, potem naciśnij Dodaj. Jest odczytywany ze schowka jednorazowo, sprawdzany przez Inworld i zapisywany na tym komputerze.",
    ["Not reachable"] = "Brak dostępu",
    ["Not used with Mature content"] = "Nie używany z treściami dla dorosłych",
    ["Ready to choose in Companion voices"] = "Gotowe do wyboru w Głosach towarzyszy",
    ["Requires an Inworld key (add it in Settings > Voices > Custom voices)"] = "Wymaga klucza Inworld (dodaj go w Ustawienia > Głosy > Własne głosy)",
    ["Speaks each companion in their own voice, on your own Inworld key. Works in English and the other languages Inworld supports. Choose it under Companion voices, where it is listed last once a key is added."] = "Każdy towarzysz mówi własnym głosem, na twoim kluczu Inworld. Działa po angielsku i w pozostałych językach obsługiwanych przez Inworld. Wybierz go w Głosach towarzyszy, gdzie po dodaniu klucza jest na końcu listy.",
    ["{voice} · needs Inworld key"] = "{voice} · wymaga klucza Inworld",
    ["Choose a character to start editing."] = "Wybierz postać, aby zacząć edycję.",
    ["Clear search"] = "Wyczyść wyszukiwanie",
    ["Companion"] = "Towarzysz",
    ["Companions"] = "Towarzysze",
    ["Custom voice"] = "Własny głos",
    ["Close"] = "Zamknij",
    ["In front of you"] = "Przed tobą",
    ["You have switched off as many people as the editor keeps ({max}). Switch one back on first."] = "Wyłączono tyle osób, ile przechowuje edytor ({max}). Najpierw włącz jedną z powrotem.",
    ["That person cannot be switched off."] = "Tej osoby nie można wyłączyć.",
    ["Don’t talk to this character"] = "Nie rozmawiaj z tą postacią",
    ["While this is on, they do not answer you and never join a group chat. Untick it to talk to them again."] = "Gdy jest włączone, nie odpowiadają ci i nigdy nie dołączają do czatu grupowego. Wyłącz to, aby znowu z nimi rozmawiać.",
    ["Switched off."] = "Wyłączone.",
    ["Switched back on."] = "Włączone z powrotem.",
    ["Switch back on"] = "Włącz z powrotem",
    ["Don’t talk to this person"] = "Nie rozmawiaj z tą osobą",
    ["It also stops everyone the game builds from the same record, so other people of the same kind may stop answering too."] = "Zatrzymuje również wszystkich, których gra buduje z tego samego rekordu, więc inne osoby tego samego rodzaju mogą również przestać odpowiadać.",
    ["Switched off"] = "Wyłączone",
    ["People and characters you chose not to talk to. Switch one back on to talk to them again."] = "Osoby i postacie, z którymi nie chcesz rozmawiać. Włącz jedną z powrotem, aby znowu z nimi rozmawiać.",
    ["Recently edited"] = "Ostatnio edytowane",
    ["Romance"] = "Romans",
    ["Romances"] = "Romanse",
    ["Side character"] = "Postać poboczna",
    ["Side characters"] = "Postacie poboczne",
    ["Minor character"] = "Postać epizodyczna",
    ["Minor characters"] = "Postacie epizodyczne",
    ["Story"] = "Fabuła",
    ["Story character"] = "Postać fabularna",
    ["Unsaved changes"] = "Niezapisane zmiany",
    ["Together"] = "Razem",
    ["You and {name} are together. This grew from talking and is kept in this save. To end it, tell them."] = "Ty i {name} jesteście razem. To wyrosło z rozmów i jest zapisane w tej grze. Aby to zakończyć, powiedz im.",
    ["A gang you keep killing may rarely send a small squad after you, with a short threat to shout. A long wait follows each one.\n\nNever in a fight, scene, call, vehicle, indoors, safe zone or while wanted."] = "Gang, który ciągle zabijasz, może rzadko wysłać mały oddział z krótką groźbą. Po każdym następuje długa przerwa.\n\nNigdy podczas walki, sceny, połączenia, w pojeździe, w budynku, w strefie bezpiecznej ani gdy jesteś poszukiwany.",
    ["A nearby companion comments as combat starts and ends, and after you collect loot from the world. Storage transfers stay silent.\n\nCooldowns: ten minutes after a fight and between ordinary loot comments, two minutes for new Legendary gear. Pickups during a fight become one comment at its end. Conversations and story scenes come first. Loading a save resets the cooldowns."] = "Towarzysz w pobliżu komentuje na początku i na końcu walki oraz po zebraniu łupów ze świata. Przeniesienia do skrytki pozostają ciche.\n\nPrzerwy: dziesięć minut po walce i między zwykłymi komentarzami o łupach, dwie minuty dla nowo zdobytego sprzętu legendarnego. Zbiory podczas walki łączą się w jeden komentarz na jej końcu. Rozmowy i sceny fabularne mają pierwszeństwo. Wczytanie zapisu resetuje przerwy.",
    ["AI provider"] = "Dostawca AI",
    ["Choose how V’s voice is used."] = "Wybierz, jak używany jest głos V.",
    ["Companion vision"] = "Wizja towarzyszy",
    ["Companion voice volume (%)"] = "Głośność głosu towarzyszy (%)",
    ["Companions react"] = "Towarzysze reagują",
    ["Each line also comes with vision: a recent view of your surroundings, taken from the game window just before you talk. Works with every conversation provider. Local AI needs a model with vision. A model without it just gets your words.\n\nOnly the game window, only while someone is near, kept briefly in memory. Off means nothing is captured."] = "Każda kwestia przychodzi też z wizją: świeżym widokiem otoczenia z okna gry, zarejestrowanym tuż przed rozmową. Działa z każdym dostawcą rozmów. Local AI potrzebuje modelu z wizją. Model bez niej dostaje tylko twoje słowa.\n\nTylko okno gry, tylko gdy ktoś jest w pobliżu, krótko w pamięci. Wyłączone: nic nie jest przechwytywane.",
    ["Error reports, developer mode and help."] = "Raporty o błędach, tryb programisty i pomoc.",
    ["How everyone sounds, and how you talk."] = "Jak brzmią wszyscy i jak się mówisz.",
    ["How the world reacts to V."] = "Jak świat reaguje na V.",
    ["Life with your party."] = "Życie z zespołem.",
    ["Night City"] = "Night City",
    ["Off: V is silent.\n\nTyped lines: the lines you type are spoken out loud too, in the V voice that matches yours, then the companion answers.\n\nTyped and spoken lines: what you say by microphone (hold to talk or Voice activation) is also spoken by V, and the reply follows V’s line.\n\nV’s line is always waited for, up to about 30 s without audio. The next row picks the voice engine."] = "Off: V jest cicha.\n\nWpisane kwestie: wpisane linie mówisz też na głos głosem V zgodnym z twoim, potem odpowiada towarzysz.\n\nWpisane i czytane kwestie: to co mówisz przez mikrofon (przytrzymaj, aby mówić, lub Aktywacja głosem) V też mówi na głos, odpowiedź następuje po kwestii V.\n\nNa linię V zawsze się czeka, najdłużej około 30 s bez dźwięku. Następny wiersz wybiera silnik głosu.",
    ["Privacy and help"] = "Prywatność i pomoc",
    ["Return to the settings categories."] = "Wróć do kategorii ustawień.",
    ["Return to {page}."] = "Wróć do {page}.",
    ["The language of the menus and how subtitles look."] = "Język menu i wygląd napisów.",
    ["The voice V speaks with, whatever the companions use. It counts only while V’s voice is not Off.\n\nPocket: on your processor, about 0.2 s (its own small model if the companions use another voice). Voxtral: cloud, with your Mistral key. OmniVoice: the companions’ GPU voice, a second more wait."] = "Głos, którym mówi V, niezależnie od tego, co używają towarzysze. Liczy się tylko gdy głos V nie jest Wyłączony.\n\nPocket: na procesorze, około 0,2 s (własny mały model, jeśli towarzysze używają innego głosu). Voxtral: w chmurze, z twoim kluczem Mistral. OmniVoice: głos GPU towarzyszy, o sekundę dłuższe oczekiwanie.",
    ["The yellow border is Windows showing a capture. Turn off Companion vision to stop it."] = "Żółta ramka: Windows pokazuje przechwycenie. Wyłącz Wizję towarzyszy, aby ją zatrzymać.",
    ["This Local AI model has no vision, so replies use only your words."] = "Ten model Local AI nie ma wizji, więc odpowiedzi zawierają tylko twoje słowa.",
    ["This model has vision with its vision file, from {folder}/vision on Hugging Face."] = "Ten model ma wizję dzięki plikowi wizji z {folder}/vision na Hugging Face.",
    ["Typed and spoken lines"] = "Wpisane i czytane kwestie",
    ["Typed lines"] = "Wpisane kwestie",
    ["Voice AI and microphone"] = "Głos AI i mikrofon",
    ["V’s voice engine"] = "Silnik głosu V",
    ["Where V is: the district, and V’s apartment or the named place when the game says so.\n\nOff: characters are not told where you are, and the mod stops reading it from the game. The vision Convai has of what V sees, and an add-on’s own text, are not affected."] = "Gdzie jest V: dzielnica oraz mieszkanie V albo nazwane miejsce, gdy gra je podaje.\n\nWyłączone: postacie nie są informowane, gdzie jesteś, a mod przestaje to odczytywać z gry. Wizja, jaką Convai dostaje o tym, co widzi V, i tekst samego dodatku nie są zmieniane.",
    ["Who writes the replies."] = "Kto pisze odpowiedzi.",
    ["Who you can talk to and what they know."] = "Z kim możesz rozmawiać i co wiedzą.",
